const d=$('Detectar pendiente importación').first().json,lot=d.context.lotId;
const rawRows=items.map(i=>i.json).filter(r=>String(r['Lote ID'])===String(lot));

function dedupeLotRows(rows){
  const rank={DESCARTADO:4,RESPONDIDO:3,LISTO:2,REVISAR:1};
  const by=new Map();
  for(const r of rows){
    const key=String(r['ID revisión']||'') || String(r['Hash movimiento']||'') || `FILA:${r.Fila||''}:${r['Descripción original']||''}`;
    const prev=by.get(key);
    if(!prev || (rank[String(r.Estado)]||0)>(rank[String(prev.Estado)]||0)){
      by.set(key,r);
    }
  }
  return [...by.values()];
}

const rows=dedupeLotRows(rawRows);
return rows.map(r=>({json:{...r,'ID revisión':r['ID revisión']||`${String(r['Lote ID']||'')}|${String(r['Hash movimiento']||'')}`,Estado:'DESCARTADO',Observaciones:`${r.Observaciones||''} Lote cancelado por Telegram.`.trim()}}));

const d=$('Detectar pendiente importación').first().json;
const ctx=d.context;
const lot=ctx.lotId;
const rawRows=items.map(i=>i.json).filter(r=>String(r['Lote ID'])===String(lot));

function dedupeLotRows(rows){
  const rank={DESCARTADO:4,RESPONDIDO:3,LISTO:2,REVISAR:1};
  const by=new Map();
  for(const r of rows){
    const key=String(r['ID revisión']||'') || String(r['Hash movimiento']||'') || `FILA:${r.Fila||''}:${r['Descripción original']||''}`;
    const prev=by.get(key);
    if(!prev || (rank[String(r.Estado)]||0)>(rank[String(prev.Estado)]||0)){
      by.set(key,r);
    }
  }
  return [...by.values()];
}

const rows=dedupeLotRows(rawRows);
function reviewRow(raw){
  if(!raw) return null;
  const r={...raw};
  const u=String(r['Descripción original']||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const cuit=String(r['CUIT contraparte']||'').replace(/\D/g,'');
  if(u.includes('primas group')){
    r['Clase sugerida']='Egreso'; r.Subtipo='Combustible'; r['Categoría sugerida']='Vehículos';
    r.Confianza=1; r.Aprendible='No';
    r.Pregunta='Categoría Vehículos asignada automáticamente.';
  } else if(u.includes('pago de servicios rivadavia') || /\brivadavia\b/.test(u)){
    r['Clase sugerida']='Egreso'; r.Subtipo='Seguro de vehículo'; r['Categoría sugerida']='Vehículos';
    r.Confianza=1; r.Aprendible='No';
    r.Pregunta='Categoría Vehículos asignada automáticamente.';
  } else if(cuit==='00000000000' &&
            String(r['Descripción original']||'').includes('01688881000082478808')){
    r['Clase sugerida']='Egreso';
    r.Subtipo='Compra / pago Mercado Libre';
    r['Categoría sugerida']='';
    r['Cuenta destino']='';
    r.Confianza=Math.min(Number(r.Confianza||0.70),0.70);
    r.Aprendible='Variable';
    r.Pregunta='No encontré un espejo confirmado en una billetera propia. ¿A qué categoría corresponde este pago de Mercado Libre?';
  } else if(
    cuit==='00000000000' ||
    ((u.includes('mercado libre') || u.includes('mercado pago')) && !cuit)
  ){
    // La plataforma agregadora no es una categoría ni identifica por sí sola al beneficiario.
    r.Aprendible='Variable'; r.Confianza=Math.min(Number(r.Confianza||0.70),0.70);
    r.Pregunta='Mercado Pago/Mercado Libre aparece como plataforma, pero no pude identificar al tercero real. ¿A qué categoría corresponde esta vez?';
  } else if((u.includes('mercado libre') || u.includes('mercado pago')) && cuit && cuit!=='00000000000'){
    // Si el banco informa CUIT/CUIL real del tercero, manda el tercero, no la plataforma.
    r['Clave aprendizaje']=r['Clave aprendizaje']||`${r.Origen}|CUIT|${cuit}`;
    if(String(r.Aprendible||'').toUpperCase()!=='NO') r.Aprendible='Sí';
    if(!r['Categoría sugerida'] && (!r.Pregunta || /Mercado (?:Libre|Pago) puede corresponder/i.test(String(r.Pregunta)))){
      const nombre=String(r['Contraparte sugerida']||'').trim();
      r.Pregunta=nombre
        ? `La transferencia fue a ${nombre} (${displayCuit(cuit)}). ¿A qué categoría corresponde?`
        : `La transferencia identifica al tercero ${displayCuit(cuit)}. ¿A qué categoría corresponde?`;
    }
  }
  return r;
}
function money(v){
  const n=Number(v||0);
  return n.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function direction(r){
  const acct=String(r['Cuenta/Tarjeta']||'');
  if(String(r['Cuenta origen']||'')===acct || r['Clase sugerida']==='Egreso' || r['Clase sugerida']==='Pago tarjeta') return 'DÉBITO';
  if(String(r['Cuenta destino']||'')===acct || r['Clase sugerida']==='Ingreso') return 'CRÉDITO';
  return 'MOVIMIENTO';
}
function fmtDate(v){
  if(!v) return null;
  const s=String(v).trim();
  let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if(m) return `${m[3]}/${m[2]}/${m[1]}`;
  return s;
}
function displayCuit(v){
  const s=String(v||'').replace(/\D/g,'');
  return s.length===11 ? `${s.slice(0,2)}-${s.slice(2,10)}-${s.slice(10)}` : String(v||'').trim();
}
function reviewGroup(r){
  const cuit=String(r['CUIT contraparte']||'').replace(/\D/g,'');
  if(cuit) return {key:`CUIT|${cuit}`,label:'mismo CUIT/CUIL'};
  const learned=String(r['Clave aprendizaje']||'').trim();
  if(learned) return {key:`KEY|${learned}`,label:'mismo concepto/comercio'};
  const detail=String(r['Descripción original']||'')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toUpperCase().replace(/\s+/g,' ').trim();
  return {key:`DET|${detail}`,label:'mismo detalle'};
}
function formattedQuestion(r, allRows=[]){
  function amountLabel(){
    const ars=Number(r['Monto ARS']);
    if(Number.isFinite(ars) && Math.abs(ars)>0.00001) return `$${money(ars)}`;
    const orig=Number(r['Monto original']);
    const cur=String(r['Moneda original']||'').trim();
    if(Number.isFinite(orig) && Math.abs(orig)>0.00001) return `${cur||'$'} ${money(orig)}`;
    return '$0,00';
  }

  const lines=[`${direction(r)} — ${amountLabel()}`];
  const fecha=fmtDate(r.Fecha);
  if(fecha) lines.push(`Fecha: ${fecha}`);

  const statement=String(r['Cuenta/Tarjeta']||'').trim();
  if(statement) lines.push(`Cuenta: ${statement}`);

  const detail=String(r['Descripción original']||'').replace(/\s+/g,' ').trim();
  if(detail) lines.push(`Detalle PDF: ${detail.length>280?detail.slice(0,277)+'...':detail}`);

  const cp=String(r['Contraparte sugerida']||'').trim();
  const cuitRaw=String(r['CUIT contraparte']||'').trim();
  const cuit=displayCuit(cuitRaw);
  if(cp) lines.push(`Contraparte detectada: ${cp}`);
  if(cuit) lines.push(`CUIT/CUIL: ${cuit}`);

  const clase=String(r['Clase sugerida']||'').toUpperCase();
  const isTransfer=clase.includes('TRANSFER') || clase.includes('PAGO TARJETA');
  if(isTransfer){
    const from=String(r['Cuenta origen']||'').trim();
    const to=String(r['Cuenta destino']||'').trim();
    if(from) lines.push(`Origen: ${from}`);
    if(to) lines.push(`Destino: ${to}`);
  }

  if(Array.isArray(allRows) && allRows.length){
    const g=reviewGroup(r);
    const same=allRows.filter(x =>
      String(x.Estado||'')!=='DESCARTADO' &&
      reviewGroup(x).key===g.key
    ).length;
    if(same>1) lines.push(`🔁 Hay ${same} movimientos con ${g.label} en este lote.`);
  }

  lines.push('');
  lines.push(r.Pregunta||'Necesito confirmar este movimiento.');
  return lines.join('\n');
}
const next0=rows.filter(r=>String(r.Estado)==='REVISAR').sort((a,b)=>Number(a.Fila||0)-Number(b.Fila||0))[0]||null;
const next=reviewRow(next0);
const ready=rows.filter(r=>['LISTO','RESPONDIDO'].includes(String(r.Estado))).length;
const discarded=rows.filter(r=>String(r.Estado)==='DESCARTADO').length;
const reviewed=rows.filter(r=>String(r.Estado)==='RESPONDIDO').length;
const now=new Date(),exp=null;
let newCtx,message,intent,field,question,options,confidence;
if(next){
  const nextId=String(next['ID revisión']||'');
  const nextSuffix=nextId.includes('|')?nextId.split('|').pop():'';
  const nextHash=/^[0-9a-f]{8}$/i.test(String(next['Hash movimiento']||''))
    ? String(next['Hash movimiento'])
    : (/^[0-9a-f]{8}$/i.test(nextSuffix)?nextSuffix:null);
  if(nextHash) next['Hash movimiento']=nextHash;
  newCtx={...ctx,type:'import_review',current_row:next,current_hash:nextHash};
  message=`✅ Respuesta guardada.\n\nQuedan ${rows.filter(r=>String(r.Estado)==='REVISAR').length} dudas.\n\n${formattedQuestion(next, rows)}`;
  intent='REVISION_IMPORTACION';field='revision_movimiento';question=formattedQuestion(next, rows);options=null;confidence=Number(next.Confianza||0);
} else {
  newCtx={...ctx,type:'import_confirm',current_row:null,current_hash:null};
  message=`✅ Revisión terminada.\n\nMovimientos a importar: ${ready}\nResueltos contigo: ${reviewed}\nDescartados: ${discarded}\n\nTodavía no impacté Movimientos.\n¿Confirmar importación? Respondé "confirmar" o "cancelar".`;
  intent='CONFIRMAR_IMPORTACION';field='confirmacion_lote';question='¿Confirmar importación?';options='confirmar | cancelar';confidence=1;
}
return [{json:{
  chat_id:d.chat_id,message,
  pending:{
    ...d.pending_row,
    "Fecha/Hora":now.toISOString(),"Intención":intent,
    "Datos parciales JSON":JSON.stringify(newCtx),"Campo pendiente":field,
    "Pregunta enviada":question,"Opciones sugeridas":options,
    "Confianza":confidence,"Estado":"PENDIENTE","Expira":""
  }
}}];

const parsed=$('Parsear PDF real').first().json;
const learned=$('Leer reglas aprendidas importación').all().map(i=>i.json).filter(r=>r['Clave regla']);
const directory=items.map(i=>i.json).filter(r=>r['CUIT/CUIL']);

function norm(s){
  return String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toUpperCase().replace(/\s+/g,' ').trim();
}
function displayCuit(c){
  const s=String(c||'').replace(/\D/g,'');
  return s.length===11?`${s.slice(0,2)}-${s.slice(2,10)}-${s.slice(10)}`:s;
}

function merchantNameFromDesc(desc){
  let s=norm(desc);
  if(s.includes('BENEF PEI-CUENTA DNI')){
    const pos=s.indexOf(' DNI ');
    if(pos>=0) s=s.slice(pos+5).trim();
    s=s.replace(/^BENEF PEI-CUENTA DNI\/?\S*\s*/,'').trim();
  } else {
    s=s.replace(/^COMPRA CT\s+\d{1,2}\/\d{1,2}\s+/,'');
    s=s.replace(/^CPRA\s+/,'');
  }
  s=s.replace(/\s*\(\d{8,}\).*$/,'').replace(/\s+AUT\s+[A-Z0-9]+.*$/,'')
  s=s.replace(/\(\d{8,}\)/g,'');
  s=s.replace(/\bAUT\s+[A-Z0-9]+\b/g,'');
  s=s.replace(/\b\d{6,}\b/g,'');
  s=s.replace(/\s+/g,' ').trim();
  let toks=s.split(' ').filter(Boolean);
  if(toks.length>=2){
    if(toks[1].startsWith(toks[0]) && toks[1]!==toks[0] && toks[0].length>=3) toks=toks.slice(1);
    else {
      let last=-1;
      for(let i=1;i<toks.length;i++) if(toks[i]===toks[0]) last=i;
      if(last>0) toks=toks.slice(last);
    }
  }
  return toks.join(' ').slice(0,80);
}
function merchantLearningKey(row){
  const d=String(row?.['Descripción original']||'');
  const u=norm(d);
  if(!(u.includes('BENEF PEI-CUENTA DNI') || u.startsWith('COMPRA CT ') || u.startsWith('CPRA '))) return null;
  const m=merchantNameFromDesc(d);
  return m ? `COMERCIO|${m}` : null;
}


function mpRecipientNameFromDesc(desc){
  const s=norm(desc);
  const m=s.match(/^TRANSFERENCIA ENVIADA\s+(.+?)\s+\d{12}\b/);
  if(!m) return null;
  return String(m[1]||'')
    .replace(/[,;]+/g,' ')
    .replace(/\s+/g,' ')
    .trim()
    .slice(0,100);
}
function mpRecipientLearningKey(row){
  const statement=norm(row?.['Cuenta/Tarjeta']||'');
  const origin=norm(row?.Origen||'');
  if(!statement.startsWith('MERCADO PAGO') && origin!=='MERCADO PAGO') return null;
  const name=mpRecipientNameFromDesc(row?.['Descripción original']||'');
  return name ? `Mercado Pago|DESTINATARIO|${name}` : null;
}

function externalAccountKey(row){
  const desc=String(row?.['Descripción original']||'');
  const cuit=(desc.match(/\b(\d{11})\b/)||[])[1]||'';
  const account=(desc.match(/\b(\d{18,22})\b/)||[])[1]||'';
  if(!account) return null;
  return `${row.Origen}|CTAEXT|${cuit||'SINCUIT'}|${account}`;
}
function applyExternalAccountMapping(row, learned){
  const key=externalAccountKey(row);
  if(!key) return false;

  // Mercado Pago/Mercado Libre usa cuentas agregadoras que NO identifican
  // una billetera propia concreta. Nunca mapear esta cuenta por aprendizaje.
  if(key==='Galicia|CTAEXT|00000000000|01688881000082478808'){
    row['Clave aprendizaje']=null;
    row.Aprendible='Variable';
    return false;
  }

  const lr=learned.find(x=>String(x['Clave regla'])===key);
  row['Clave aprendizaje']=key;
  row.Aprendible='Sí';
  if(!lr) return false;

  const state=String(lr.Estado||'').toUpperCase();
  const value=String(lr['Valor sugerido']||'').trim();
  const conf=Number(lr.Confianza||0);

  if(state==='VARIABLE' || value==='VARIABLE'){
    row.Estado='REVISAR';
    row.Confianza=Math.min(Number(row.Confianza||0),0.70);
    row['Motivo revisión']='La misma cuenta externa tuvo asignaciones distintas';
    row.Pregunta='Esta cuenta externa tuvo asignaciones distintas anteriormente. ¿A qué cuenta nuestra corresponde esta vez?';
    row.Aprendible='Variable';
    return true;
  }
  if(state==='AUTO' && value){
    const statementAccount=String(row['Cuenta/Tarjeta']||'');
    if(row['Cuenta origen'] && !row['Cuenta destino']){
      row['Cuenta destino']=value;
    } else if(row['Cuenta destino'] && !row['Cuenta origen']){
      row['Cuenta origen']=value;
    } else {
      const u=norm(row['Descripción original']);
      if(u.includes('TRANSFERENCIA A TERCEROS') || u.includes('TRANSF. CTAS PROPIAS')){
        row['Cuenta origen']=row['Cuenta origen']||statementAccount;
        row['Cuenta destino']=value;
      } else if(u.includes('TRANSFERENCIA DE TERCEROS') || u.includes('TRANSFERENCIA DE CUENTA PROPIA')){
        row['Cuenta origen']=value;
        row['Cuenta destino']=row['Cuenta destino']||statementAccount;
      } else {
        return false;
      }
    }
    row['Clase sugerida']='Transferencia';
    row.Subtipo='Transferencia familiar / propia';
    row.Confianza=Math.max(Number(row.Confianza||0),conf||1);
    row.Estado=(row['Cuenta origen'] && row['Cuenta destino'] && row.Confianza>=0.95)?'LISTO':'REVISAR';
    row['Motivo revisión']=row.Estado==='LISTO'?'Cuenta contraparte aprendida y coincidente':'Falta completar la transferencia';
    row.Pregunta=row.Estado==='LISTO'?null:'Necesito confirmar la cuenta contraparte.';
    row.Aprendible='No';
    return true;
  }
  if(state==='SUGERIR' && value){
    row.Estado='REVISAR';
    row.Confianza=Math.max(Number(row.Confianza||0),Math.min(conf||0.90,0.90));
    row['Motivo revisión']='Cuenta contraparte sugerida por aprendizaje previo';
    row.Pregunta=`La vez anterior esta cuenta externa correspondió a ${value}. ¿Es la misma cuenta?`;
    return true;
  }
  return false;
}
function pattern(desc){
  let s=norm(desc);
  s=s.replace(/^COMPRA CT\s+\d{1,2}\/\d{1,2}\s+/,'');
  s=s.replace(/^CPRA\s+/,'');
  s=s.replace(/^PAGO DE SERVICIOS\s+/,'');
  s=s.replace(/^\*\s*/,'');
  s=s.replace(/\bC\.\d{1,2}\/\d{1,2}\b/g,'');
  s=s.replace(/\b\d{1,2}\/\d{1,2}\b/g,'');
  s=s.replace(/\bAUT\s+[A-Z0-9]+\b/g,'');
  s=s.replace(/\(\d{8,}\)/g,'');
  s=s.replace(/\b\d{6,}\b/g,'');
  s=s.replace(/\bVAR(?:IOS)?\b/g,'');
  s=s.replace(/\s+/g,' ').trim();
  return s.slice(0,70);
}

const patternCounts={};
for(const r0 of parsed.rows){
  const eligible0 = r0['Clase sugerida']==='Egreso' && !r0['Categoría sugerida'] &&
    ['Compra','Consumo tarjeta','Pago servicio','Débito automático','Comisión seguro'].includes(r0['Subtipo']);
  if(eligible0){
    const p0=pattern(r0['Descripción original']);
    const k0=`${r0.Origen}|CAT|${p0}`;
    patternCounts[k0]=(patternCounts[k0]||0)+1;
  }
}

for(const row of parsed.rows){
  const urow=norm(row['Descripción original']);
  const rawDesc=String(row['Descripción original']||'');
  const cuitFromDesc=(rawDesc.match(/\b((?:20|23|24|27|30|33|34)\d{9})\b/)||[])[1]||'';
  const compactCuit=String(row['CUIT contraparte']||cuitFromDesc||'').replace(/\D/g,'');
  if(compactCuit && !row['CUIT contraparte']) row['CUIT contraparte']=compactCuit;
  const extAccount=(rawDesc.match(/\b(\d{18,22})\b/)||[])[1]||'';

  // Balanz identificado por CUIT en Galicia USD.
  // Créditos = rescate Balanz -> Galicia USD; débitos = aporte Galicia USD -> Balanz.
  if(
    String(row['Cuenta/Tarjeta']||'')==='Galicia USD Titular A' &&
    (compactCuit==='00000000000' || urow.includes('BALANZ CAPITAL VALOR'))
  ){
    const incoming=!!row['Cuenta destino'] || String(row['Clase sugerida']||'')==='Ingreso';
    row['Clase sugerida']='Transferencia';
    row.Subtipo=incoming?'Rescate inversión':'Aporte inversión';
    row['Cuenta origen']=incoming?'Balanz':'Galicia USD Titular A';
    row['Cuenta destino']=incoming?'Galicia USD Titular A':'Balanz';
    row['Categoría sugerida']=null;
    row.Confianza=1;
    row.Estado='LISTO';
    row['Motivo revisión']=incoming
      ?'CUIT Balanz reconocido: rescate a Galicia USD'
      :'CUIT Balanz reconocido: aporte desde Galicia USD';
    row.Pregunta=null;
    row['Clave aprendizaje']=null;
    row.Aprendible='No';
    continue;
  }

  // Transferencias de Mercado Pago Titular B contra la propia Titular B:
  // dentro del sistema familiar, la contraparte es Provincia Titular B.
  if(String(row['Cuenta/Tarjeta']||'')==='Mercado Pago Titular B' && /TITULAR B\s*[, ]\s*TITULAR B/i.test(rawDesc)){
    const received=/TRANSFERENCIA RECIBIDA/i.test(rawDesc);
    const sent=/TRANSFERENCIA ENVIADA/i.test(rawDesc);
    if(received || sent){
      row['Clase sugerida']='Transferencia';
      row.Subtipo='Transferencia propia';
      row['Cuenta origen']=received?'Provincia Titular B':'Mercado Pago Titular B';
      row['Cuenta destino']=received?'Mercado Pago Titular B':'Provincia Titular B';
      row['Categoría sugerida']=null;
      row.Confianza=1;
      row.Estado='LISTO';
      row['Motivo revisión']='Transferencia propia Titular B inferida por titular + inventario de cuentas familiares';
      row.Pregunta=null;
      row['Clave aprendizaje']=null;
      row.Aprendible='No';
      continue;
    }
  }

  // Transferencias Galicia -> beneficiarios vía Mercado Libre:
  // usar nombre + CUIT del beneficiario, no "Mercado Libre" como regla genérica.
  if(urow.includes('TRANSFERENCIA A TERCEROS') && urow.includes('MERCADO LIBRE') && compactCuit && compactCuit!=='00000000000'){
    const mName=rawDesc.match(/TRANSFERENCIA A TERCEROS\s+(.+?)\s+((?:20|23|24|27|30|33|34)\d{9})\b/i);
    if(mName && !row['Contraparte sugerida']) row['Contraparte sugerida']=String(mName[1]||'').trim();
    row['Fuente contraparte']='Detalle del resumen bancario';
    row['Confianza contraparte']=1;
  }


  // Regla fija confirmada por uso real:
  // En Banco Provincia, créditos "TRANSF DE TITULAR_A ... VAR 0000000000"
  // corresponden a transferencias desde Galicia Titular A.
  if(
    String(row.Origen||'')==='Provincia' &&
    urow.includes('TRANSF DE TITULAR_A') &&
    urow.includes('0000000000')
  ){
    const statement=String(row['Cuenta/Tarjeta']||'').trim();
    if(statement){
      row['Clase sugerida']='Transferencia';
      row.Subtipo='Transferencia propia';
      row['Cuenta origen']='Galicia Titular A';
      row['Cuenta destino']=statement;
      row['Categoría sugerida']=null;
      row.Confianza=1;
      row.Estado='LISTO';
      row['Motivo revisión']='Patrón VAR 0000000000 confirmado como transferencia desde Galicia Titular A';
      row.Pregunta=null;
      row['Clave aprendizaje']=null;
      row.Aprendible='No';
      continue;
    }
  }

  // Cuenta agregadora Mercado Pago / Mercado Libre.
  // Esta cuenta NO identifica una billetera propia concreta (Titular A/Titular B).
  // Primero la conciliación universal intentará encontrar un espejo real.
  // Si no existe espejo, se trata como pago/compra y se pregunta categoría.
  if(compactCuit==='00000000000' && extAccount==='01688881000082478808'){
    const statement=String(row['Cuenta/Tarjeta']||'Galicia Titular A');
    row['Clase sugerida']='Egreso';
    row.Subtipo='Compra / pago Mercado Libre';
    row['Cuenta origen']=row['Cuenta origen']||statement||'Galicia Titular A';
    row['Cuenta destino']=null;
    row['Categoría sugerida']=null;
    row.Confianza=Math.min(Number(row.Confianza||0.70),0.70);
    row.Estado='REVISAR';
    row['Motivo revisión']='Cuenta agregadora Mercado Pago/Mercado Libre: requiere espejo real o categoría';
    row.Pregunta='No encontré un espejo confirmado en una billetera propia. ¿A qué categoría corresponde este pago de Mercado Libre?';
    row['Clave aprendizaje']=null;
    row.Aprendible='Variable';
    continue;
  }

  // Categoría unificada de vehículos: ya no se pregunta Fiesta/Suran.
  if(urow.includes('primas group')){
    row['Clase sugerida']='Egreso';
    row.Subtipo='Combustible';
    row['Categoría sugerida']='Vehículos';
    row.Confianza=1;
    row.Estado='LISTO';
    row['Motivo revisión']='PRIMAS GROUP automatizado a Vehículos';
    row.Pregunta=null;
    row['Clave aprendizaje']=null;
    row.Aprendible='No';
    continue;
  }

  if(urow.includes('pago de servicios rivadavia') || /\brivadavia\b/.test(urow)){
    row['Clase sugerida']='Egreso';
    row.Subtipo='Seguro de vehículo';
    row['Categoría sugerida']='Vehículos';
    row.Confianza=1;
    row.Estado='LISTO';
    row['Motivo revisión']='Seguro RIVADAVIA automatizado a Vehículos';
    row.Pregunta=null;
    row['Clave aprendizaje']=null;
    row.Aprendible='No';
    continue;
  }

  if(/\bcombustible\b/.test(urow) || /\bgnc\b/.test(urow) || /\bpatente\b/.test(urow)){
    row['Clase sugerida']='Egreso';
    row.Subtipo=/\bpatente\b/.test(urow)?'Patente / impuesto vehículo':'Combustible';
    row['Categoría sugerida']='Vehículos';
    row.Confianza=1;
    row.Estado='LISTO';
    row['Motivo revisión']='Concepto automotor inequívoco automatizado a Vehículos';
    row.Pregunta=null;
    row['Clave aprendizaje']=null;
    row.Aprendible='No';
    continue;
  }

  const marketPlatformMention=
    urow.includes('mercado libre') || urow.includes('mercado pago');
  const marketBeneficiaryTransfer=
    urow.includes('TRANSFERENCIA A TERCEROS') &&
    marketPlatformMention &&
    !!compactCuit &&
    compactCuit!=='00000000000';

  if(compactCuit==='00000000000' || (marketPlatformMention && !marketBeneficiaryTransfer && !compactCuit)){
    row.Estado='REVISAR';
    row.Confianza=Math.min(Number(row.Confianza||0.70),0.70);
    row['Motivo revisión']='Plataforma Mercado Pago/Mercado Libre sin tercero identificable';
    row.Pregunta='Mercado Pago/Mercado Libre aparece como plataforma, pero no pude identificar al tercero real. ¿A qué categoría corresponde esta vez?';
    row['Clave aprendizaje']=null;
    row.Aprendible='Variable';
    continue;
  }

  // Si aparece Mercado Pago/Mercado Libre pero el extracto trae CUIT real de un tercero,
  // la clasificación se aprende por ese CUIT. La plataforma es sólo el medio de pago.

  // Excepción permanente: DI BENEDETTO, LUCIAN puede corresponder a motivos distintos.
  // Nunca aplicar reglas previas ni aprender automáticamente.
  if(urow.includes('DI BENEDETTO') || compactCuit==='00000000000'){
    row.Estado='REVISAR';
    row.Confianza=Math.min(Number(row.Confianza||0.70),0.70);
    row['Motivo revisión']='Contraparte marcada como variable: preguntar siempre';
    row.Pregunta='DI BENEDETTO, LUCIAN puede corresponder a distintos motivos. ¿Cómo querés registrar este movimiento esta vez?';
    row['Clave aprendizaje']=null;
    row.Aprendible='Variable';
    continue;
  }


  // Aprendizaje por comercio: una misma categoría se reutiliza en compras y reintegros.
  const merchantKey=merchantLearningKey(row);
  if(merchantKey){
    row['Clave aprendizaje']=merchantKey;
    row.Aprendible='Sí';
    const mlr=learned.find(x=>String(x['Clave regla'])===merchantKey);
    const isBenefit=urow.includes('BENEF PEI-CUENTA DNI');

    if(mlr){
      const mstate=String(mlr.Estado||'').toUpperCase();
      const mvalue=String(mlr['Valor sugerido']||'').trim();
      const mconf=Number(mlr.Confianza||0);

      if(mstate==='AUTO' && mvalue){
        row['Categoría sugerida']=mvalue;
        if(isBenefit){
          row['Clase sugerida']='Egreso';
          row.Subtipo='Ajuste / reintegro de gasto';
          row['Cuenta destino']=row['Cuenta destino']||row['Cuenta/Tarjeta'];
        } else {
          row['Clase sugerida']=row['Clase sugerida']==='Otro'?'Egreso':row['Clase sugerida'];
          row.Subtipo=row.Subtipo||'Compra';
          row['Cuenta origen']=row['Cuenta origen']||row['Cuenta/Tarjeta'];
        }
        row.Confianza=Math.max(Number(row.Confianza||0),mconf||1);
        row.Estado='LISTO';
        row['Motivo revisión']='Comercio aprendido por confirmación del usuario';
        row.Pregunta=null;
        continue;
      }

      if(mstate==='VARIABLE'){
        row.Estado='REVISAR';
        row.Confianza=Math.min(Number(row.Confianza||0),0.70);
        row['Motivo revisión']='Este comercio tuvo categorías distintas';
        row.Pregunta=`El comercio ${merchantNameFromDesc(row['Descripción original'])} tuvo clasificaciones distintas. ¿A qué categoría corresponde esta vez?`;
        row.Aprendible='Variable';
      }
    }
  }

  const accountMapped=applyExternalAccountMapping(row, learned);
  if(accountMapped && row.Estado==='LISTO') continue;

  const cuit=String(row['CUIT contraparte']||'').replace(/\D/g,'');
  let dir=null;
  if(cuit){
    dir=directory.find(x=>String(x['CUIT/CUIL']||'').replace(/\D/g,'')===cuit)||null;
    if(dir){
      row['Contraparte sugerida']=dir['Nombre / razón social']||row['Contraparte sugerida'];
      row['Fuente contraparte']=dir['URL fuente']||dir.Fuente||row['Fuente contraparte'];
      row['Confianza contraparte']=Number(dir['Confianza identidad']||0);
      const state=String(dir['Estado identidad']||'').toUpperCase();
      if(state==='PROPIO/FAMILIA'){
        row['Clase sugerida']='Transferencia';
        row.Subtipo='Transferencia familiar / propia';
        row.Confianza=Math.max(Number(row.Confianza||0),0.80);
        row.Estado='REVISAR';
        row['Motivo revisión']='Contraparte propia/familiar identificada localmente; falta cuenta destino exacta';
        row.Pregunta=`El CUIT/CUIL ${displayCuit(cuit)} corresponde a ${row['Contraparte sugerida']}. Parece una transferencia propia/familiar. ¿A qué cuenta fue?`;
      } else if(row.Estado==='REVISAR' && row['Contraparte sugerida']){
        row.Pregunta=`El CUIT/CUIL ${displayCuit(cuit)} está guardado localmente como ${row['Contraparte sugerida']}. ¿Qué fue este movimiento y a qué categoría corresponde si fue un gasto?`;
      }
    } else if(row.Estado==='REVISAR'){
      row['Motivo revisión']='CUIT/CUIL no conocido localmente; requiere respuesta del usuario';
      row.Pregunta=`No conozco todavía el CUIT/CUIL ${displayCuit(cuit)}. ¿Sabés a qué corresponde este movimiento? Podés responder, por ejemplo: "gasto comida", "gasto Casa" o "transferencia a Galicia".`;
    }
  }

  const recipientKey=mpRecipientLearningKey(row);
  const cuitEligible = !!cuit && row['Cuenta origen'] && !dir?.['Estado identidad']?.toString().toUpperCase().includes('PROPIO');
  const regularEligible = row['Clase sugerida']==='Egreso' && !row['Categoría sugerida'] &&
    ['Compra','Consumo tarjeta','Pago servicio','Débito automático','Comisión seguro'].includes(row['Subtipo']);
  const merchantEligible = !!merchantKey;
  const recipientEligible = !!recipientKey && row['Clase sugerida']==='Egreso' && !row['Categoría sugerida'];

  if(!cuitEligible && !regularEligible && !merchantEligible && !recipientEligible){
    if(row['Clave aprendizaje'] && String(row['Clave aprendizaje']).includes('|CTAEXT|')){
      continue;
    }
    row['Clave aprendizaje']=null;
    row['Aprendible']='No';
    continue;
  }

  const p=cuitEligible?cuit:pattern(row['Descripción original']);
  const key=recipientKey || merchantKey || (cuitEligible?`${row.Origen}|CUIT|${cuit}`:`${row.Origen}|CAT|${p}`);
  row['Clave aprendizaje']=key;
  row['Aprendible']='Sí';
  const lr=learned.find(x=>String(x['Clave regla'])===key);
  if(!lr){
    // Solo patrones cuyo significado es inequívocamente comida.
    if(!merchantKey && !recipientKey && /\b(PARRILLA|PANADERIA|CARNES|PASTAS|PESCADO)\b/.test(p)){
      row['Categoría sugerida']='Comida';
      row.Confianza=Math.max(Number(row.Confianza||0),0.96);
      row.Estado='LISTO';
      row['Motivo revisión']='Comercio/tipo inequívocamente gastronómico';
      row.Pregunta=null;
      row.Aprendible='No';
      continue;
    }
    if(patternCounts[key]>1 && row.Estado==='REVISAR'){
      row.Pregunta=`${row.Pregunta} Hay ${patternCounts[key]} movimientos con el mismo patrón. Si todos corresponden igual, podés responder "todos <categoría>".`;
    }
    continue;
  }
  const state=String(lr.Estado||'').toUpperCase();
  const value=lr['Valor sugerido'];
  const conf=Number(lr.Confianza||0);
  if(state==='AUTO' && value){
    row['Categoría sugerida']=value;
    if((key.includes('|CUIT|') || key.includes('|DESTINATARIO|')) && row['Cuenta origen']) {
      row['Clase sugerida']='Egreso';
      if(key.includes('|DESTINATARIO|')) row.Subtipo='Transferencia a tercero';
      else row.Subtipo=row.Subtipo||'Pago a contraparte';
    }
    row.Confianza=Math.max(Number(row.Confianza||0),conf);
    row.Estado=row.Confianza>=0.95?'LISTO':'REVISAR';
    row['Motivo revisión']=row.Estado==='LISTO'?'Clasificación aprendida confirmada':'Sugerencia aprendida';
    row.Pregunta=row.Estado==='LISTO'?null:`¿Lo registro como ${value}?`;
  } else if(state==='SUGERIR' && value){
    row['Categoría sugerida']=value;
    if((key.includes('|CUIT|') || key.includes('|DESTINATARIO|')) && row['Cuenta origen']) {
      row['Clase sugerida']='Egreso';
      if(key.includes('|DESTINATARIO|')) row.Subtipo='Transferencia a tercero';
      else row.Subtipo=row.Subtipo||'Pago a contraparte';
    }
    row.Confianza=Math.max(Number(row.Confianza||0),Math.min(conf,0.90));
    row.Estado='REVISAR';
    row['Motivo revisión']='Sugerencia aprendida con una sola confirmación';
    row.Pregunta=`La vez anterior lo clasificaste como ${value}. ¿Lo registro igual esta vez?${patternCounts[key]>1?` Hay ${patternCounts[key]} iguales; podés responder "todos ${value}".`:''}`;
  } else if(state==='VARIABLE'){
    row['Aprendible']='Variable';
    row.Estado='REVISAR';
    row.Confianza=Math.min(Number(row.Confianza||0),0.70);
    row['Motivo revisión']='Este patrón tuvo clasificaciones distintas';
    row.Pregunta=`Este concepto tuvo clasificaciones diferentes anteriormente. ¿A qué categoría corresponde esta vez?${patternCounts[key]>1?' Si solo algunos son iguales, no uses "todos".':''}`;
  }
}
