function norm(s){return String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/\s+/g,' ').trim();}
function merchantNameFromDesc(desc){
  let s=norm(desc);
  if(s.includes('BENEF PEI-CUENTA DNI')){
    const pos=s.indexOf(' DNI ');
    if(pos>=0) s=s.slice(pos+5).trim();
    s=s.replace(/^BENEF PEI-CUENTA DNI\/?\S*\s*/,'').trim();
  } else {
    s=s.replace(/^COMPRA CT\s+\d{1,2}\/\d{1,2}\s+/,'').replace(/^CPRA\s+/,'');
  }
  s=s.replace(/\s*\(\d{8,}\).*$/,'').replace(/\s+AUT\s+[A-Z0-9]+.*$/,'');
  s=s.replace(/\(\d{8,}\)/g,'').replace(/\bAUT\s+[A-Z0-9]+\b/g,'').replace(/\b\d{6,}\b/g,'').replace(/\s+/g,' ').trim();
  let toks=s.split(' ').filter(Boolean);
  if(toks.length>=2){
    if(toks[1].startsWith(toks[0]) && toks[1]!==toks[0] && toks[0].length>=3) toks=toks.slice(1);
    else {let last=-1;for(let i=1;i<toks.length;i++) if(toks[i]===toks[0]) last=i;if(last>0) toks=toks.slice(last);}
  }
  return toks.join(' ').slice(0,80);
}
function merchantLearningKey(row){
  const d=String(row?.['Descripción original']||'');
  const u=norm(d);
  if(!(u.includes('BENEF PEI-CUENTA DNI')||u.startsWith('COMPRA CT ')||u.startsWith('CPRA '))) return null;
