  const clase=String(r['Clase sugerida']||'').toUpperCase();
  const isTransfer=clase.includes('TRANSFER') || clase.includes('PAGO TARJETA');
  if(isTransfer){
    const from=String(r['Cuenta origen']||'').trim();
    const to=String(r['Cuenta destino']||'').trim();
    if(from) lines.push(`Origen: ${from}`);
    if(to) lines.push(`Destino: ${to}`);
  }

  if(Array.isArray(allRows) && allRows.length){
    const g=reviewGroup(r);
    const same=allRows.filter(x =>
      String(x.Estado||'')!=='DESCARTADO' &&
      reviewGroup(x).key===g.key
    ).length;
    if(same>1) lines.push(`🔁 Hay ${same} movimientos con ${g.label} en este lote.`);
  }

  lines.push('');
