function pickText(obj) {
  const preferred = ['text','content','data','extractedText','rawText'];
  for (const k of preferred) if (typeof obj[k] === 'string' && obj[k].length > 40) return obj[k];
  const candidates = Object.values(obj).filter(v => typeof v === 'string' && v.length > 40);
  candidates.sort((a,b)=>b.length-a.length);
  return candidates[0] || '';
}
