function simpleHash(s) {
  let h1 = 0x811c9dc5;
  for (let i=0;i<s.length;i++) {
    h1 ^= s.charCodeAt(i);
    h1 = Math.imul(h1, 0x01000193);
  }
  return ('00000000'+(h1>>>0).toString(16)).slice(-8);
}
