}
const esMonths={ene:1,enero:1,feb:2,febrero:2,mar:3,marzo:3,abr:4,abril:4,may:5,mayo:5,jun:6,junio:6,jul:7,julio:7,ago:8,agosto:8,sep:9,set:9,sept:9,septiembre:9,setiembre:9,oct:10,octubre:10,nov:11,noviembre:11,dic:12,diciembre:12};
function iso(y,m,d){return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;}
function parseDateRaw(s, fallbackYear=2026) {
  const x=norm(s);
  let m=x.match(/\b(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})\b/);
  if (m){let y=+m[3]; if(y<100)y+=2000; return iso(y,+m[2],+m[1]);}
  m=x.match(/\b(\d{1,2})-(ene|feb|mar|abr|may|jun|jul|ago|sep|set|sept|oct|nov|dic)-(\d{2,4})\b/i);
  if(m){let y=+m[3];if(y<100)y+=2000;return iso(y,esMonths[m[2].toLowerCase()],+m[1]);}
  m=x.match(/\b(\d{1,2})\s+(ene|enero|feb|febrero|mar|marzo|abr|abril|may|mayo|jun|junio|jul|julio|ago|agosto|sep|set|sept|septiembre|setiembre|oct|octubre|nov|noviembre|dic|diciembre)\s+(\d{2,4})\b/i);
  if(m){let y=+m[3];if(y<100)y+=2000;return iso(y,esMonths[m[2].toLowerCase()],+m[1]);}
  return null;
}


// Extrae el período sin depender del layout interno del PDF.
// Busca fechas alrededor de la etiqueta "Período de movimientos" y reconstruye
// día/mes/año a partir de tokens numéricos, tolerando espacios, saltos y caracteres raros.
function extractStatementPeriod(raw){
  const s=norm(raw);
  const up=upper(s);

  // Primer intento: patrón semántico real del resumen Galicia:
  // FECHA_DESDE FECHA_HASTA Período de movimientos.
  const direct=s.match(/(\d{1,2})\s*[\/.-]\s*(\d{1,2})\s*[\/.-]\s*(20\d{2})\s+(\d{1,2})\s*[\/.-]\s*(\d{1,2})\s*[\/.-]\s*(20\d{2})\s+PERIODO DE MOVIMIENTOS/i);
  if(direct){
    return {
      from:iso(Number(direct[3]),Number(direct[2]),Number(direct[1])),
      to:iso(Number(direct[6]),Number(direct[5]),Number(direct[4])),
      source:'direct_period_label'
    };
  }

  const idx=up.indexOf('PERIODO DE MOVIMIENTOS');
  const windows=[];
  if(idx>=0) windows.push(s.slice(Math.max(0,idx-500),Math.min(s.length,idx+250)));
  windows.push(s);

  function datesFromWindow(w){
    const toks=String(w).match(/\d+/g)||[];
    const out=[];
    const add=(d,m,y)=>{
      d=Number(d);m=Number(m);y=Number(y);
      if(y<2000||y>2099||m<1||m>12||d<1||d>31) return;
      const v=iso(y,m,d);
      if(v&&!out.includes(v)) out.push(v);
    };
    for(let i=0;i<toks.length;i++){
      const t=toks[i];
      // Caso compacto DDMMYYYY.
      if(/^\d{8}$/.test(t)){
        const dd=+t.slice(0,2), mm=+t.slice(2,4), yyyy=+t.slice(4,8);
        if(yyyy>=2000&&yyyy<=2099) add(dd,mm,yyyy);
      }
      // Caso fragmentado: DD / MM / YYYY, incluso si el PDF separó cada parte.
      if(i+2<toks.length && toks[i].length<=2 && toks[i+1].length<=2 && /^20\d{2}$/.test(toks[i+2])){
        add(toks[i],toks[i+1],toks[i+2]);
      }
    }
    return out;
  }

  for(const w of windows){
    const ds=datesFromWindow(w);
    if(ds.length>=2) return {from:ds[0],to:ds[1],source:'period_label_tokens'};
  }
  return {from:null,to:null,source:'not_found'};
}
