      return makeRow({origin,account,date,desc,amount,clase:'Transferencia',subtipo:'Extracción efectivo',from:account||'Galicia Titular A',to:usdAccount?'Efectivo USD':'Efectivo',confidence:1,currency:usdAccount?'USD':'ARS'});
    }
    if(u.includes('ACREDITAMIENTO DE HABERES')) return makeRow({origin,account,date,desc,amount,clase:'Ingreso',subtipo:'Sueldo',to:'Galicia Titular A',cat:'Sueldo Titular A',confidence:1});
    if(u.includes('TRANSF. CTAS PROPIAS')) return makeRow({origin,account,date,desc,amount,clase:'Transferencia',subtipo:'Entre cuentas propias',from:'Galicia Titular A',to:null,confidence:.75,reason:'Falta cuenta contrapartida'});
    if(u.includes('TRANSFERENCIA DE CUENTA PROPIA')) return makeRow({origin,account,date,desc,amount,clase:'Transferencia',subtipo:'Entre cuentas propias',from:null,to:'Galicia Titular A',confidence:.75,reason:'Falta cuenta contrapartida'});
    if(u.includes('TRANSFERENCIAS MEP')) return makeRow({origin,account,date,desc,amount,clase:'Transferencia',subtipo:'MEP / inversión',from:null,to:'Galicia Titular A',confidence:.60,reason:'No asumir que corresponde a Balanz',question:`¿El movimiento MEP por $${ar(Math.abs(amount))} corresponde a Balanz u otra operación?`});
    if(u.includes('REINTEGRO PROMOCION GALICIA')) return makeRow({origin,account,date,desc,amount,clase:'Otro',subtipo:'Reintegro',to:'Galicia Titular A',confidence:.70,reason:'Falta regla para reintegros',question:`¿Cómo querés tratar el reintegro "${desc}" por $${ar(Math.abs(amount))}: reducir el gasto original o registrarlo de otra forma?`});
    if(u.includes('PAGO DE SERVICIOS')) return makeRow({origin,account,date,desc,amount,clase:'Egreso',subtipo:'Pago servicio',from:'Galicia Titular A',confidence:.80,reason:'Falta categoría'});
    if(u.includes('TRANSFERENCIA A TERCEROS')) return makeRow({origin,account,date,desc,amount,clase:'Otro',subtipo:'Transferencia a tercero',from:'Galicia Titular A',confidence:.55,reason:'Puede ser gasto o transferencia'});
    return makeRow({origin,account,date,desc,amount,clase:credit?'Ingreso':'Egreso',subtipo:'Otro',from:debit?'Galicia Titular A':null,to:credit?'Galicia Titular A':null,confidence:.55,reason:'Concepto no aprendido'});
  }
  if(origin==='Provincia'){
    if(u.includes('ACREDIT. INTERESES')) return makeRow({origin,account,date,desc,amount,clase:'Resultado financiero',subtipo:'Interés / rendimiento',to:account,confidence:1});
    if(u.includes('PAGO VISA')) {
