        question:cardDest?null:'¿Este pago Visa corresponde a la tarjeta Provincia de Titular A o de Titular B?'});
    }
    if(u.includes('CREDITO HABERES')) return makeRow({origin,account,date,desc,amount,clase:'Ingreso',subtipo:'Sueldo',to:account,cat:account==='Provincia Titular B'?'Sueldo Titular B':'Sueldo Titular A',confidence:1});
    if(u.includes('CR. SAC/HSEX/OTROS')) return makeRow({origin,account,date,desc,amount,clase:'Ingreso',subtipo:'Sueldo',to:account,cat:account==='Provincia Titular B'?'Sueldo Titular B':'Sueldo Titular A',confidence:1});
    if(u.includes('COMPRA CT')) return makeRow({origin,account,date,desc,amount,clase:'Egreso',subtipo:'Compra',from:account,confidence:.80,reason:'Falta categoría del comercio'});
    if(u.includes('BENEF PEI-CUENTA DNI')) return makeRow({origin,account,date,desc,amount,clase:'Otro',subtipo:'Reintegro Cuenta DNI',to:account,confidence:.70,reason:'Tratamiento de reintegros pendiente',question:`¿Cómo querés tratar este beneficio/reintegro de Cuenta DNI por $${ar(Math.abs(amount))}?`});
    if(u.includes('DB.DEBIN')) {
      const cuit=extractCuitCounterparty(desc);

      // Regla familiar determinística:
      // Titular B tiene Provincia Titular B + Mercado Pago Titular B.
      // Si un débito desde Provincia Titular B identifica a la propia Titular B por CUIT,
      // la otra cuenta propia posible es Mercado Pago Titular B.
      if(account==='Provincia Titular B' && cuit==='00000000000'){
        return makeRow({
          origin,account,date,desc,amount,
          clase:'Transferencia',subtipo:'Transferencia propia',
          from:'Provincia Titular B',to:'Mercado Pago Titular B',
          confidence:1,
          reason:'Cuenta propia inferida por titular + CUIT + inventario de cuentas familiares',
          external:`CUIT:${cuit}`,cuit
        });
      }

      return makeRow({origin,account,date,desc,amount,clase:'Otro',subtipo:'DEBIN',from:account,
        confidence:cuit?.length===11?.62:.55,
        reason:cuit?'CUIT/CUIL detectado; requiere clasificación del usuario':'Puede ser gasto o transferencia',
        question:cuit?`El DEBIN informa CUIT/CUIL ${displayCuit(cuit)}. ¿Sabés a qué corresponde este movimiento? Podés responder, por ejemplo: "gasto comida" o "transferencia a Galicia".`:null,
        external:cuit?`CUIT:${cuit}`:'',cuit});
    }
    if(u.startsWith('CDNI')) {
      const cuit=extractCuitCounterparty(desc);
      return makeRow({origin,account,date,desc,amount,clase:'Otro',subtipo:'Cuenta DNI',from:account,
        confidence:cuit?.length===11?.62:.55,
        reason:cuit?'CUIT/CUIL detectado; requiere clasificación del usuario':'Puede ser gasto o transferencia',
        question:cuit?`Cuenta DNI informa CUIT/CUIL ${displayCuit(cuit)}. ¿Sabés a qué corresponde este movimiento? Podés responder, por ejemplo: "gasto comida" o "transferencia a Provincia Titular A".`:null,
        external:cuit?`CUIT:${cuit}`:'',cuit});
    }
    if(u.startsWith('TRANSF DE ')){
      const isTitular B=u.includes('TITULAR_B') || u.includes('00000000000');
      const isTitular A=u.includes('TITULAR_A') || u.includes('00000000000');

      // Si Provincia Titular B recibe una transferencia cuyo ordenante es la propia Titular B,
      // el origen se infiere como Mercado Pago Titular B. Si el ordenante es Titular A,
      // no se infiere porque Titular A tiene varias cuentas posibles.
      if(account==='Provincia Titular B' && isTitular B){
        return makeRow({
          origin,account,date,desc,amount,
          clase:'Transferencia',subtipo:'Transferencia propia',
          from:'Mercado Pago Titular B',to:'Provincia Titular B',
          confidence:1,
          reason:'Cuenta propia inferida por titular + CUIT/nombre + inventario de cuentas familiares'
        });
      }

      const known=isTitular B||isTitular A;
      return makeRow({
        origin,account,date,desc,amount,
        clase:known?'Transferencia':'Otro',
        subtipo:'Transferencia recibida',
        from:null,to:account,
        confidence:known?.75:.55,
        reason:known?'Falta cuenta origen exacta':'Puede ser ingreso o reintegro'
      });
    }
    if(u.includes('COMISION SEGURO')) return makeRow({origin,account,date,desc,amount,clase:'Egreso',subtipo:'Comisión seguro',from:account,confidence:.75,reason:'Falta categoría'});
    return makeRow({origin,account,date,desc,amount,clase:credit?'Ingreso':'Egreso',subtipo:'Otro',from:debit?account:null,to:credit?account:null,confidence:.55,reason:'Concepto no aprendido'});
  }
  if(origin==='Nación'){
    if(u.includes('RENDIMIENTO DIARIO PESOS') || u.includes('INTERESES CAPITALIZADOS')) return makeRow({origin,account,date,desc,amount,clase:'Resultado financiero',subtipo:'Interés / rendimiento',to:'Nación',confidence:1});
    if(u.includes('PM/TOT.MC')) return makeRow({origin,account,date,desc,amount,clase:'Pago tarjeta',subtipo:'Pago tarjeta',from:'Nación',to:'Tarjeta Titular A Nación',confidence:1});
    if(
      u.includes('DEB. TRANSF. INTERB.') ||
      u.includes('DB.TRANSF.INTER-LINK') ||
      u.includes('DEB. TRANSF. IN-LINK') ||
      u.includes('CR.TRANSF.INTER-LINK') ||
      u.startsWith('TRANSFERENCIA ') ||
      u.startsWith('DEBIN ')
    ){
      return makeRow({
        origin,account,date,desc,amount,
        clase:'Transferencia',
        subtipo:credit?'Transferencia recibida':'Transferencia enviada',
        from:debit?'Nación':null,
        to:credit?'Nación':null,
        confidence:.70,
        reason:credit?'Falta cuenta origen':'Falta cuenta destino'
      });
    }
    if(u.includes('CPRA ') || u.includes('COMPRA MAESTRO')) return makeRow({origin,account,date,desc,amount,clase:'Egreso',subtipo:'Compra',from:'Nación',confidence:.80,reason:'Falta categoría'});
    if(u.includes('ACREDIT. PROMOCION MODO')) return makeRow({origin,account,date,desc,amount,clase:'Otro',subtipo:'Reintegro',to:'Nación',confidence:.70,reason:'Falta categoría del gasto reintegrado'});
    if(u.includes('DEBITO AUTOMATICO')) return makeRow({origin,account,date,desc,amount,clase:'Egreso',subtipo:'Débito automático',from:'Nación',confidence:.65,reason:'Concepto/categoría no visible'});
    return makeRow({origin,account,date,desc,amount,clase:credit?'Ingreso':'Egreso',subtipo:'Otro',from:debit?'Nación':null,to:credit?'Nación':null,confidence:.55,reason:'Concepto no aprendido'});
  }
  if(origin==='Mercado Pago'){
    if(u.includes('RENDIMIENTOS')) return makeRow({origin,account,date,desc,amount,clase:'Resultado financiero',subtipo:'Interés / rendimiento',to:account,confidence:1});
    if(u.includes('OBRA SOCIAL') || u.includes('OSPE')) return makeRow({origin,account,date,desc,amount,clase:'Egreso',subtipo:'Pago servicio',from:account,cat:'Salud',confidence:.99});

    // Titular B sólo tiene dos cuentas operativas propias en este circuito: MP Titular B y Provincia Titular B.
    // Si el resumen de MP Titular B dice TITULAR_B, el otro lado es determinístico.
    const selfTitular B=/TITULAR B[,\s]*TITULAR B/i.test(String(desc||''));
    if(account==='Mercado Pago Titular B' && selfTitular B && u.includes('TRANSFERENCIA ENVIADA')){
      return makeRow({origin,account,date,desc,amount,clase:'Transferencia',subtipo:'Transferencia propia',from:'Mercado Pago Titular B',to:'Provincia Titular B',confidence:1,reason:'Transferencia interna Titular B determinística'});
    }
    if(account==='Mercado Pago Titular B' && selfTitular B && u.includes('TRANSFERENCIA RECIBIDA')){
      return makeRow({origin,account,date,desc,amount,clase:'Transferencia',subtipo:'Transferencia propia',from:'Provincia Titular B',to:'Mercado Pago Titular B',confidence:1,reason:'Transferencia interna Titular B determinística'});
    }

    return makeRow({origin,account,date,desc,amount,clase:credit?'Ingreso':'Egreso',subtipo:'Otro',from:debit?account:null,to:credit?account:null,confidence:.60,reason:'Concepto no aprendido'});
  }
}

function cardExpense(card,date,desc,amount,cat=null,conf=.8,sub='Consumo tarjeta',currency='ARS',originalAmount=null) {
  const u=upper(desc);

  // Galicia: DB.RG 5617 es una percepción condicionada al pago en pesos del saldo USD.
  // Regla familiar: el saldo USD se paga en USD, por lo que no integra gasto ni deuda efectiva.
  // Se conserva en staging/control documental para que el resumen siga conciliando.
  if(card==='Tarjeta Galicia Titular A' && /DB\.RG\s*5617/i.test(String(desc||''))){
    const r=makeRow({
      origin:'Tarjeta',account:card,date,desc,amount,
      clase:'Ajuste patrimonial',subtipo:'Percepción condicional por saldo USD',
      from:card,cat:null,confidence:1,
      reason:'No computa como gasto ni deuda efectiva porque el saldo USD se paga en USD',
      currency,originalAmount
    });
    r.Estado='DESCARTADO';
    r.Observaciones='Percepción condicional: se conserva para conciliación documental, pero no se importa a Movimientos.';
    return r;
  }

  if(u.includes('IMPUESTO DE SELLOS')) {cat='Impuestos';conf=1;sub='Impuesto tarjeta';}
  else if(u.includes('INTERESES FINANCIACION')) {cat='Gastos financieros';conf=1;sub='Interés financiación';}
  else if(u.includes('DB IVA')||u.includes('IIBB PERCEP')||u.includes('IVA RG')||u.includes('DB.RG')) {cat='Impuestos';conf=1;sub='Impuesto / percepción';}
  else if(u.includes('NETFLIX')) {cat='Ocio';conf=.99;}
  return makeRow({origin:'Tarjeta',account:card,date,desc,amount,clase:'Egreso',subtipo:sub,from:card,cat,confidence:conf,reason:cat?'':'Falta categoría del consumo',currency,originalAmount});
}

function groupByDate(lines, regex) {
  const out=[]; let current=null;
  const stop=/^(Total\b|Fecha de generaci[oó]n:|Esta informaci[oó]n es la que consta|Resumen de Cuenta Sueldo\s+P[aá]gina|RESUMEN DE TENENCIAS|P[aá]gina\s+\d+\s+de)/i;
  for(const line0 of lines){
    const line=norm(line0); if(!line) continue;
    if(stop.test(line)){
      if(current){ out.push(current); current=null; }
      continue;
    }
    if(regex.test(line)){
      if(current) out.push(current);
      current=line;
    } else if(current) current+=' '+line;
  }
  if(current) out.push(current);
  return out;
}

