  coverageDeclared=(periodFrom && periodTo && closingBalanceDate===periodTo && isMonthEndIso(periodTo))?'Sí':'Parcial';
  balanceMethod='RESUMEN_POSICION_FIMA';
  balanceNote=(units!==null && unitValue!==null && closingBalance!==null)
    ?`Resumen de Posición FIMA. Cuotapartes: ${units}; valor cuota: ${unitValue}; saldo valorizado: ${closingBalance}. Aportes del período: ${subscriptions}; rescates: ${withdrawals}.`
    :'Resumen de Posición FIMA incompleto.';
  fimaControl={units,unitValue,subscriptions,withdrawals,opCount};

} else if(U.includes('RESUMEN DE CAJA DE AHORRO EN DOLARES') || U.includes('CAJA DE AHORRO EN DOLARES')) {
