  if(!close && headDates.length>=3) close=parseDateRaw(headDates[2]);
  if(!due && headDates.length>=4) due=parseDateRaw(headDates[3]);

  const totalM=text.match(/TOTAL A PAGAR\s+([\d.,]+)\s+([\d.,]+)/i);
  const minM=text.match(/PAGO MINIMO[\s\S]{0,100}?En pesos[\s\S]{0,30}?\$\s*([\d.,]+)/i)
    || text.match(/Plan V:\s*abonando el pago m[ií]nimo de\s*\$\s*([\d.,]+)/i);
  const totalArs=totalM?parseMoney(totalM[1]):null;
  const totalUsd=totalM?parseMoney(totalM[2]):0;
  const min=minM?parseMoney(minM[1]):null;
  cardSummary={card:account,holder:'Titular A',close,due,totalArs,totalUsd,min};
  vencimiento={concepto:'Tarjeta Galicia Titular A',fecha:due,importe:totalArs};
  periodFrom=close;periodTo=close;

  // Parseo robusto del detalle: se corta exactamente en "Total Consumos" y se agrupa
  // por fecha, sin depender de que cada consumo venga en una línea separada.
  const detail=(text.split(/DETALLE DEL CONSUMO/i)[1]||'').split(/TARJETA\s+\d+\s+Total Consumos/i)[0]||'';
  const txRe=/(\d{2}-\d{2}-\d{2})\s+([\s\S]*?)(?=(?:\s+\d{2}-\d{2}-\d{2}\b)|$)/g;
  for(const m of detail.matchAll(txRe)){
    const body=norm(m[2]);
    if(!body) continue;
    const toks=moneyTokens(body); if(!toks.length) continue;

    if(/USD/i.test(body)){
      const um=body.match(/USD\s*([\d.,]+)/i);
      const usd=um?parseMoney(um[1]):toks[toks.length-1].value;
      const desc=norm(body.replace(/USD\s*[\d.,]+/i,' USD').replace(toks[toks.length-1].raw,' '));
      rows.push(cardExpense(account,close,desc,null,null,.8,'Consumo tarjeta','USD',usd));
    } else {
      const amount=toks[toks.length-1].value;
      const desc=norm(body.replace(toks[toks.length-1].raw,' '));
      rows.push(cardExpense(account,close,desc,amount));
    }
  }

  // Cargos, intereses e impuestos posteriores al detalle.
  for(const line0 of text.split('\n')){
    const line=norm(line0);
    if(!/(IMPUESTO DE SELLOS|INTERESES FINANCIACION|DB IVA|IIBB PERCEP|IVA RG|DB\.RG)/i.test(line)) continue;
    const toks=moneyTokens(line); if(!toks.length) continue;
    rows.push(cardExpense(account,close,line,toks[toks.length-1].value));
  }

  // Total de percepciones condicionadas que aparecen en el resumen pero no forman
  // parte de la deuda económica si el saldo USD se cancela en USD.
  cardSummary.conditionalArs=rows
    .filter(r=>r.Subtipo==='Percepción condicional por saldo USD')
    .reduce((a,r)=>a+Number(r['Monto ARS']||0),0);
} else if(U.includes('MASTERCARD PLATINUM') && U.includes('BANCO NACION')) {
  docType='tarjeta_nacion'; origin='Tarjeta'; account='Tarjeta Titular A Nación';
  const close=closingDateFromText(text), due=dueDateFromText(text);
  const totalM=text.match(/Saldo actual:\s*\$\s*([\d.,]+)\s+U\$S\s*([\d.,]+)/i);
  const minM=text.match(/Pago Minimo:\s*\$\s*([\d.,]+)/i);
  const totalArs=totalM?parseMoney(totalM[1]):null,totalUsd=totalM?parseMoney(totalM[2]):0,min=minM?parseMoney(minM[1]):null;
  cardSummary={card:account,holder:'Titular A',close,due,totalArs,totalUsd,min};
  vencimiento={concepto:'Tarjeta Titular A Nación',fecha:due,importe:totalArs};
  periodFrom=close;periodTo=close;
  const sec=(text.split(/DETALLE DEL MES/i)[1]||'').split(/TOTAL TITULAR/i)[0];
  let inInstallments=false;
  for(const line0 of sec.split('\n')){
    const line=norm(line0);
    if(/^CUOTAS DEL MES\b/i.test(line)){inInstallments=true;continue;}
    const dm=line.match(/^(\d{2}-[A-Za-z]{3}-\d{2})\s+/);
    if(!dm) continue;
    const originalDate=parseDateRaw(dm[1]);
    if(!originalDate) throw new Error(`Fecha no reconocida en resumen Nación: ${dm[1]}`);
    const toks=moneyTokens(line); if(!toks.length) continue;
    const desc=norm(line.replace(/^\d{2}-[A-Za-z]{3}-\d{2}\s*/,'').replace(toks[toks.length-1].raw,' '));
    if(/SU PAGO/i.test(desc)) continue;
    // Compras y débitos: fecha real de operación. Cuotas: período imputado en el resumen.
    const movementDate=inInstallments?close:originalDate;
    const row=cardExpense(account,movementDate,desc,toks[toks.length-1].value);
    row.Observaciones=inInstallments
      ?`Cuota imputada al cierre ${close}. Compra original: ${originalDate}.`
      :`Fecha de operación del PDF: ${originalDate}. Resumen cerrado: ${close}.`;
    rows.push(row);
  }
  const stamp=text.match(/IMPUESTO DE SELLOS\s+([\d.,]+)/i);
  if(stamp) rows.push(cardExpense(account,close,'IMPUESTO DE SELLOS',parseMoney(stamp[1])));
} else if(U.includes('PROV BS AIRES') && U.includes('VENCIMIENTO') && U.includes('VISA')) {
  docType='tarjeta_provincia'; origin='Tarjeta';
  const isTitular B=U.includes('TITULAR B,TITULAR B');
  const isTitular A=U.includes('TITULAR A');
  account=isTitular B?'Tarjeta Provincia Titular B':(isTitular A?'Tarjeta Provincia Titular A':null);
  const holder=isTitular B?'Titular B':(isTitular A?'Titular A':null);
  const close=closingDateFromText(text), due=dueDateFromText(text);
  const totalM=text.match(/DEBITAREMOS DE SU CTA\s+\d+\s+LA SUMA DE\s+\$\s*([\d.,]+)/i);
  const totalConsM=text.match(/Total Consumos de [^\n]*?\s+([\d.,]+)\s*\*\s*([\d.,]+)\s*\*/i);
  const minM=text.match(/PAGO MINIMO[\s\S]{0,80}?([\d.,]+)\s*(?:BANCO|$)/i) || text.match(/Plan V: abonando el pago mínimo de \$\s*([\d.,]+)/i);
  // Si el extractor pierde la leyenda DEBITAREMOS, Total Consumos es una fuente independiente válida.
  const totalArs=totalM?parseMoney(totalM[1]):(totalConsM?parseMoney(totalConsM[1]):null),min=minM?parseMoney(minM[1]):null;
  cardSummary={card:account,holder,close,due,totalArs,totalUsd:0,min};
  vencimiento={concepto:account||'Tarjeta Provincia',fecha:due,importe:totalArs};
  periodFrom=close;periodTo=close;

  // Sólo el bloque entre SALDO ANTERIOR y Total Consumos contiene consumos/pagos.
  // Evita interpretar tasas como CFTNA 79,00% como un gasto de $79.
  const provSection=(text.split(/SALDO ANTERIOR/i)[1]||'');
  const provBlock=provSection.split(/(?:Tarjeta\s+\d+\s+)?Total Consumos/i)[0]||'';
  for(const line0 of provBlock.split('\n')){
    const line=norm(line0);
    if(!line || /SU PAGO/i.test(line)) continue;
    if(/TNAV|TEM\b|TEAV|CFTNA|TASA DE|VIGENTES SON|LEY\s*25065|%\s*\(\*\)/i.test(line)) continue;
    // Los consumos reales empiezan por un número de fecha/día y contienen el separador * del comercio.
    if(/^\d{1,2}\b/.test(line) && line.includes('*') && moneyTokens(line).length){
      const toks=moneyTokens(line);
      const amount=toks[toks.length-1].value;
      const desc=norm(line.replace(toks[toks.length-1].raw,' '));
      rows.push(cardExpense(account,close,desc,amount));
    }
  }
  // Impuesto de sellos puede venir después de Total Consumos: se toma sólo si la línea lo declara explícitamente.
  for(const line0 of text.split('\n')){
    const line=norm(line0);
    if(!/IMPUESTO DE SELLOS\s+\$/i.test(line)) continue;
    const toks=moneyTokens(line); if(!toks.length) continue;
    rows.push(cardExpense(account,close,line,toks[toks.length-1].value));
  }
}

if(docType==='desconocido'){
  rows=[makeRow({origin:'Desconocido',account:null,date:null,desc:`Formato no reconocido: ${filename}`,amount:0,clase:null,confidence:0,reason:'Formato no soportado',question:'No reconocí el formato del PDF. ¿De qué banco/plataforma/tarjeta es?'})];
}

// Banco Provincia: COBERTURA es un movimiento técnico interno que suele aparecer como crédito+débito
// por el mismo importe en días contiguos. Sólo se descarta cuando existe la contrapartida verificable.
if(docType==='banco_provincia'){
  const cov=rows.map((r,i)=>({r,i,desc:upper(r['Descripción original']||''),amt:Number(r['Monto ARS']||0),date:String(r.Fecha||'')}))
    .filter(x=>x.desc.includes('COBERTURA'));
  const used=new Set();
  const day=(s)=>{const d=new Date(String(s)+'T00:00:00Z');return isNaN(d)?null:Math.floor(d.getTime()/86400000);};
  for(const a of cov){
    if(used.has(a.i)) continue;
    const aDebit=a.desc.includes('DEBITO COBERTURA');
    const aCredit=a.desc.includes('CREDITO COBERTURA');
    if(!aDebit&&!aCredit) continue;
    const mate=cov.find(b=>!used.has(b.i)&&b.i!==a.i&&Math.abs(b.amt-a.amt)<0.01&&((aDebit&&b.desc.includes('CREDITO COBERTURA'))||(aCredit&&b.desc.includes('DEBITO COBERTURA')))&&day(a.date)!==null&&day(b.date)!==null&&Math.abs(day(a.date)-day(b.date))<=3);
    if(!mate) continue;
    for(const x of [a,mate]){
      rows[x.i].Estado='DESCARTADO';
      rows[x.i].Confianza=1;
      rows[x.i]['Motivo revisión']='Movimiento técnico COBERTURA compensado dentro del banco';
      rows[x.i].Pregunta='';
      rows[x.i].Aprendible='No';
      rows[x.i].Observaciones=`COBERTURA interna compensada con fila ${x.i===a.i?mate.i+1:a.i+1}; no impacta ingresos/gastos.`;
    }
    used.add(a.i); used.add(mate.i);
  }
}
const occurrence={};
rows.forEach((r,i)=>{
  r["Fila"]=i+1;
  const base=[r["Origen"],r["Cuenta/Tarjeta"],r["Fecha"],r["Descripción original"],r["Monto ARS"],r["Moneda original"],r["Monto original"],r["CUIT contraparte"]||''].join('|');
  occurrence[base]=(occurrence[base]||0)+1;
  r["Hash movimiento"]=simpleHash(base+'|'+occurrence[base]);
});
const ready=rows.filter(r=>r.Estado==='LISTO').length;
const review=rows.filter(r=>r.Estado==='REVISAR').length;
const discarded=rows.filter(r=>r.Estado==='DESCARTADO').length;


function absn(v){ return v===null||v===undefined||v===''?null:Math.abs(Number(v)); }
function sumRows(filterFn, field='Monto ARS'){
  return rows.filter(filterFn).reduce((a,r)=>{
    const v=r[field];
    return a + ((v===null||v===undefined||v==='')?0:Number(v));
  },0);
}
function buildDocumentControl(){
  const tol=0.02;
  const c={
    level:'NO DISPONIBLE',status:'SIN CONTROL',block:false,
    declaredIn:null,calcIn:null,diffIn:null,
    declaredOut:null,calcOut:null,diffOut:null,
    declaredTotalArs:null,calcTotalArs:null,diffTotalArs:null,
    declaredTotalUsd:null,calcTotalUsd:null,diffTotalUsd:null,
    openingDeclared:openingBalance,closingDeclared:closingBalance,
    closingCalc:null,diffClosing:null,message:''
  };
  const fail=(v)=>v!==null && Math.abs(v)>tol;
  const signed=(raw)=>raw===null||raw===undefined?null:parseMoney(raw);
  const currentChargesArs=()=>sumRows(r=>r['Monto ARS']!==null && r['Monto ARS']!==undefined);
  const currentChargesUsd=()=>sumRows(r=>String(r['Moneda original']||'ARS').toUpperCase()==='USD','Monto original');
  const consumptionArs=()=>sumRows(r=>r.Subtipo==='Consumo tarjeta' && r['Monto ARS']!==null && r['Monto ARS']!==undefined);
  const consumptionUsd=()=>sumRows(r=>r.Subtipo==='Consumo tarjeta' && String(r['Moneda original']||'ARS').toUpperCase()==='USD','Monto original');

  if(docType==='fima_posicion'){
    const f=fimaControl||{};
    const calcClose=(f.units!==null&&f.units!==undefined&&f.unitValue!==null&&f.unitValue!==undefined)
      ? Math.round((Number(f.units)*Number(f.unitValue))*100)/100
      : null;
    c.declaredIn=f.subscriptions??0;
    c.calcIn=f.subscriptions??0;
    c.diffIn=0;
    c.declaredOut=f.withdrawals??0;
    c.calcOut=f.withdrawals??0;
    c.diffOut=0;
    c.closingCalc=calcClose;
    c.diffClosing=(closingBalance!==null&&calcClose!==null)?Math.round((closingBalance-calcClose)*100)/100:null;
    const full=coverageDeclared==='Sí' && !!periodFrom && !!periodTo && periodTo===closingBalanceDate;
    const essentials=closingBalance!==null && f.units!==null && f.unitValue!==null;
    c.level=full?'FUERTE':'PARCIAL';
    c.status=(full&&essentials&&!fail(c.diffClosing))?'OK':(full?'REVISAR':'PARCIAL');
    c.block=full && c.status!=='OK';
    c.message=c.status==='OK'
      ?`Resumen FIMA completo. Posición ${closingBalanceDate}; ${f.opCount||0} operaciones. Saldo valorizado = cuotapartes × valor cuota. Aportes ${f.subscriptions||0}; rescates ${f.withdrawals||0}.`
      :(c.status==='PARCIAL'
        ?'Resumen FIMA parcial: la posición no corresponde al último día del mes completo.'
        :'El resumen FIMA no pasó el control de posición valorizada.');
    return c;
  }

  if(docType==='banco_galicia_usd'){
    c.level='FUERTE';
    const tm=norm(text).match(/Total\s+USD\s*([\d.,]+)\s+-?USD\s*([\d.,]+)\s+USD\s*([\d.,]+)/i);
    const financialMetadataOk=!!(openingBalanceUsd!==null && closingBalanceUsd!==null);
    const periodComplete=!!(periodFrom && periodTo);
    if(tm && financialMetadataOk){
      c.declaredInUsd=parseMoney(tm[1]);
      c.declaredOutUsd=parseMoney(tm[2]);
      c.closingDeclaredUsd=parseMoney(tm[3]);
      c.calcInUsd=sumRows(r=>r['Cuenta destino']===account,'Monto original');
      c.calcOutUsd=sumRows(r=>r['Cuenta origen']===account,'Monto original');
      c.diffInUsd=c.calcInUsd-c.declaredInUsd;
      c.diffOutUsd=c.calcOutUsd-c.declaredOutUsd;
      if(openingBalanceUsd!==null){
        c.closingCalcUsd=openingBalanceUsd+c.calcInUsd-c.calcOutUsd;
        c.diffClosingUsd=c.closingCalcUsd-c.closingDeclaredUsd;
      }
      c.status=(fail(c.diffInUsd)||fail(c.diffOutUsd)||fail(c.diffClosingUsd))?'REVISAR':'OK';
      c.block=c.status==='REVISAR';
      c.message=c.status==='OK'
        ?('Créditos, débitos y saldo final USD coinciden con el extracto Galicia USD.'+
          (periodComplete?'':' Advertencia: el período completo no pudo extraerse; no bloquea la conciliación financiera.'))
        :`No cierra Galicia USD. Dif. créditos USD ${ar(c.diffInUsd||0)}, débitos USD ${ar(c.diffOutUsd||0)}, saldo USD ${ar(c.diffClosingUsd||0)}.`;
    } else {
      c.status='REVISAR'; c.block=true;
      const missing=[];
      if(openingBalanceUsd===null) missing.push('saldo inicial USD');
      if(closingBalanceUsd===null) missing.push('saldo final USD');
      if(!tm) missing.push('línea Total USD');
      c.message='No pude validar financieramente: '+(missing.length?missing.join(', '):'control documental Galicia USD')+'.';
    }

  } else if(docType==='banco_galicia'){
    c.level='FUERTE';
    const tm=text.match(/Total\s+\$\s*([\d.]+,\d{2})\s+-\$\s*([\d.]+,\d{2})\s+\$\s*([\d.]+,\d{2})/i);
    const financialMetadataOk=!!(openingBalance!==null && closingBalance!==null);
    const periodComplete=!!(periodFrom && periodTo);
    if(tm && financialMetadataOk){
      c.declaredIn=parseMoney(tm[1]); c.declaredOut=parseMoney(tm[2]);
      c.closingDeclared=parseMoney(tm[3]);
      c.calcIn=sumRows(r=>r['Cuenta destino']===account);
      c.calcOut=sumRows(r=>r['Cuenta origen']===account);
      c.diffIn=c.calcIn-c.declaredIn;
      c.diffOut=c.calcOut-c.declaredOut;
      if(openingBalance!==null){
        c.closingCalc=openingBalance+c.calcIn-c.calcOut;
        c.diffClosing=c.closingCalc-c.closingDeclared;
      }
      c.status=(fail(c.diffIn)||fail(c.diffOut)||fail(c.diffClosing))?'REVISAR':'OK';
      c.block=c.status==='REVISAR';
      c.message=c.status==='OK'
        ?('Créditos, débitos y saldo final coinciden con el total del extracto.'+
          (periodComplete?'':' Advertencia: el período completo no pudo extraerse; no bloquea la conciliación financiera.'))
        :`No cierra el extracto. Dif. créditos ${ar(c.diffIn||0)}, débitos ${ar(c.diffOut||0)}, saldo ${ar(c.diffClosing||0)}.`;
    } else {
      c.status='REVISAR'; c.block=true;
      const missing=[];
      if(openingBalance===null) missing.push('saldo inicial ARS');
      if(closingBalance===null) missing.push('saldo final ARS');
      if(!tm) missing.push('línea Total ARS');
      c.message='No pude validar financieramente: '+(missing.length?missing.join(', '):'control documental Galicia ARS')+'.';
    }

  } else if(docType==='mercado_pago'){
    c.level='FUERTE';
    const mt=norm(text);
    const em=mt.match(/Entradas\s*:?\s*\$\s*([\d.,]+)/i);
    const sm=mt.match(/Salidas\s*:?\s*\$\s*(-?[\d.,]+)/i);
    const fm=mt.match(/Saldo\s+final\s*:?\s*\$\s*([\d.,]+)/i);

    // En un resumen mensual completo exigimos también período y saldos.
    const metadataOk=!!(periodFrom && periodTo && openingBalance!==null && closingBalance!==null);

    if(em&&sm&&fm&&metadataOk){
      c.declaredIn=absn(parseMoney(em[1]));
      c.declaredOut=absn(parseMoney(sm[1]));
      c.closingDeclared=parseMoney(fm[1]);
      c.calcIn=sumRows(r=>r['Cuenta destino']===account);
      c.calcOut=sumRows(r=>r['Cuenta origen']===account);
      c.diffIn=c.calcIn-c.declaredIn;
      c.diffOut=c.calcOut-c.declaredOut;
      c.closingCalc=openingBalance+c.calcIn-c.calcOut;
      c.diffClosing=c.closingCalc-c.closingDeclared;
      c.status=(fail(c.diffIn)||fail(c.diffOut)||fail(c.diffClosing))?'REVISAR':'OK';
      c.block=c.status==='REVISAR';
      c.message=c.status==='OK'
        ?'Período, saldo inicial, entradas, salidas y saldo final coinciden con el resumen de Mercado Pago.'
        :`No cierra Mercado Pago. Dif. entradas ${ar(c.diffIn||0)}, salidas ${ar(c.diffOut||0)}, saldo ${ar(c.diffClosing||0)}.`;
    } else {
      c.status='REVISAR';
      c.block=true;
      c.message='No pude validar período + saldo inicial + entradas/salidas + saldo final de Mercado Pago. El lote queda bloqueado para evitar confirmar un resumen incompleto.';
    }

  } else if(docType==='tarjeta_galicia'){
    c.level='FUERTE';
    c.declaredTotalArs=cardSummary?.totalArs??null;
    c.declaredTotalUsd=cardSummary?.totalUsd??0;

    const prev=text.match(/SALDO ANTERIOR\s+(-?[\d.,]+-?)\s+(-?[\d.,]+-?)/i);
    const prevArs=prev?parseMoney(prev[1]):0, prevUsd=prev?parseMoney(prev[2]):0;
    let adjArs=0, adjUsd=0;
    const cons=(text.split(/CONSOLIDADO/i)[1]||'').split(/DETALLE DEL CONSUMO/i)[0]||'';

    // Pagos: buscar sobre todo el bloque, no línea por línea.
    // El extractor PDF puede insertar saltos de línea dentro de una operación.
    for(const m of cons.matchAll(/SU PAGO EN PESOS\s+(-?[\d.,]+-?)/gi)){
      const v=parseMoney(m[1]); if(v!==null) adjArs+=v;
    }
    // Galicia puede rotular el pago en moneda extranjera como "SU PAGO EN USD"
    // o como "SU PAGO EN DOLARES" según el formato del resumen.
    for(const m of cons.matchAll(/SU PAGO EN (?:D[ÓO]LARES|USD)\s+(-?[\d.,]+-?)/gi)){
      const v=parseMoney(m[1]); if(v!==null) adjUsd+=v;
    }

    // DEV.IMP. RG 5617 es la devolución de la percepción condicional del período anterior.
    // Como la familia paga el saldo USD en USD, ni la percepción original ni su devolución
    // son gasto/ingreso económico; sí deben entrar en la ecuación documental del resumen.
    for(const line0 of cons.split('\n')){
      const line=norm(line0);
      if(!/DEV\.?\s*IMP\.?\s*RG\s*5617/i.test(line)) continue;
      const toks=moneyTokens(line);
      if(toks.length) adjArs+=Number(toks[toks.length-1].value||0);
    }

    // TRANSFERENCIA DEUDA Galicia:
    // deuda USD original | TC | contravalor ARS | baja deuda USD.
    // \s acepta también saltos de línea introducidos por el extractor.
    for(const m of cons.matchAll(/TRANSFERENCIA DEUDA\s+(-?[\d.,]+)\s+TC\s*([\d.,]+)\s+(-?[\d.,]+)\s+(-?[\d.,]+)/gi)){
      const ars=parseMoney(m[3]);
      const usd=parseMoney(m[4]);
      if(ars!==null) adjArs+=ars;
      if(usd!==null) adjUsd+=usd;
    }
    c.calcTotalArs=prevArs+adjArs+currentChargesArs();
    c.calcTotalUsd=prevUsd+adjUsd+currentChargesUsd();
    c.diffTotalArs=c.calcTotalArs-(c.declaredTotalArs??0);
    c.diffTotalUsd=c.calcTotalUsd-(c.declaredTotalUsd??0);

    const dm=text.match(/Total Consumos de [^\n]*?\s+([\d.,]+)\s+([\d.,]+)/i);
    const dca=dm?parseMoney(dm[1]):null, dcu=dm?parseMoney(dm[2]):null;
    const diffConsArs=dca===null?null:consumptionArs()-dca;
    const diffConsUsd=dcu===null?null:consumptionUsd()-dcu;
    const bad=fail(c.diffTotalArs)||fail(c.diffTotalUsd)||fail(diffConsArs)||fail(diffConsUsd);
    c.status=bad?'REVISAR':'OK'; c.block=bad;
    c.message=bad
      ?`No cierra Visa Galicia. Dif. saldo final ARS ${ar(c.diffTotalArs||0)}, USD ${ar(c.diffTotalUsd||0)}, consumos ARS ${ar(diffConsArs||0)}, consumos USD ${ar(diffConsUsd||0)}.`
      :'Saldo anterior + pagos/conversión + cargos actuales = total a pagar, y el detalle de consumos también coincide.';

  } else if(docType==='tarjeta_nacion'){
    c.level='FUERTE';
    c.declaredTotalArs=cardSummary?.totalArs??null;
    c.declaredTotalUsd=cardSummary?.totalUsd??0;
    const pend=text.match(/SALDO PENDIENTE\s+([\d.,]+)\s+([\d.,]+)/i);
