function sideDates(r,clase,origin,dest){
  if(String(clase||'')!=='Transferencia') return {fo:null,fd:null,state:null};
  const date=r.Fecha||null;
  const statement=String(r['Cuenta/Tarjeta']||'').trim();
  const u=norm(r['Descripción original']);
  let fo=null,fd=null;
  if(statement && origin===statement) fo=date;
  if(statement && dest===statement) fd=date;
  if(!fo && !fd && date){
    if(u.includes('RECIBIDA') || u.includes('DE TERCEROS') || u.includes('CREDITO') || u.includes('CR.TRANSF') || u.includes('CR. TRANSF')) fd=date;
    else if(u.includes('ENVIADA') || u.includes('A TERCEROS') || u.includes('DEBITO') || u.includes('DB.TRANSF') || u.includes('DEB. TRANSF') || u.includes('PAGO CON TRANSFERENCIA')) fo=date;
    else if(origin && !dest) fo=date;
    else if(dest && !origin) fd=date;
  }
  const internal=ownAccounts.has(String(origin||'')) && ownAccounts.has(String(dest||''));
  if(internal){
    const needsMirror=documentary(origin) && documentary(dest);
    if(!needsMirror && date){ fo=fo||date; fd=fd||date; }
    return {fo,fd,state:(fo&&fd)?'CONCILIADA':(needsMirror?'PENDIENTE_ESPEJO':'CONCILIADA_SIN_ESPEJO')};
