const accounts=['Provincia Titular A','Provincia Titular B','Galicia Titular A','Galicia USD Titular A','Nación','Mercado Pago Titular A','Mercado Pago Titular B','Efectivo','FIMA','Balanz','Pellegrini +','Tarjeta Galicia Titular A','Tarjeta Provincia Titular A','Tarjeta Provincia Titular B','Tarjeta Titular A Nación'];

function catFromText(){
  // Alias históricos de los dos autos hacia la categoría unificada.
  if(/\b(fiesta|suran|vehiculo|vehiculos)\b/.test(t)) return 'Vehículos';
  // Buscar primero las categorías más específicas/largas.
  // Evita que "Cositas de Casa" sea interpretado como "Casa".
  const ordered=[...categories].sort((a,b)=>norm(b).length-norm(a).length);
  for(const c of ordered) if(t.includes(norm(c))) return c;
  return null;
}
function counterpartyFromText(){
  if(!row['CUIT contraparte'] || row['Contraparte sugerida']) return null;
  const raw=String(text||'').trim();
  // Ejemplos aceptados:
  // "es Sangre y Tierra, gasto comida"
  // "corresponde a Juan Perez - transferencia a Galicia"
  // "nombre Sangre y Tierra; gasto Casa"
  let m=raw.match(/^(?:es|es de|corresponde a|nombre[:\s]+)\s+(.+?)(?=\s*[,;.-]\s*|\s+(?:gasto|transferencia|ingreso|pago|comida|casa|salud|educaci[oó]n|ocio|impuestos|veh[ií]culos?|fiesta|suran)\b)/i);
  if(!m) return null;
  const name=m[1].trim();
  return name.length>=2 && name.length<=80 ? name : null;
}

function accountMentionsFromText(){
  const aliasEntries=[
    ['Provincia Titular A',[
      'provincia titular_a','provincia de titular_a','titular_a provincia',
      'provincia san','cuenta titular_a provincia','cuenta provincia titular_a'
    ]],
    ['Provincia Titular B',[
      'provincia titular_b','provincia de titular_b','titular_b provincia',
      'cuenta titular_b provincia','cuenta provincia titular_b'
    ]],
    ['Galicia USD Titular A',[
      'galicia usd titular_a','galicia usd','cuenta dolares galicia','cuenta dólares galicia',
      'dolares galicia','dólares galicia','usd galicia'
    ]],
    ['Galicia Titular A',[
      'galicia titular_a','galicia de titular_a','titular_a galicia','galicia'
    ]],
    ['Nación',['nacion','bna']],
    ['Mercado Pago Titular A',[
      'mercado pago titular_a','mercado pago de titular_a','titular_a mercado pago',
      'mp titular_a','mp san','titular_a mp'
    ]],
    ['Mercado Pago Titular B',[
      'mercado pago titular_b','mercado pago de titular_b','titular_b mercado pago',
      'mp titular_b','titular_b mp'
    ]],
    ['Efectivo',['efectivo']],
    ['FIMA',['fima']],
    ['Balanz',['balanz']],
    ['Pellegrini +',['pellegrini +','pellegrini plus','pellegrini','fci premium']],
    ['Tarjeta Galicia Titular A',['tarjeta galicia','visa galicia']],
    ['Tarjeta Provincia Titular A',[
      'tarjeta provincia titular_a','tarjeta provincia de titular_a','visa provincia titular_a'
    ]],
    ['Tarjeta Provincia Titular B',[
      'tarjeta provincia titular_b','tarjeta provincia de titular_b','visa provincia titular_b'
    ]],
    ['Tarjeta Titular A Nación',['tarjeta nacion','mastercard nacion','nativa']]
  ];

  const candidates=[];
  for(const [account, aliases] of aliasEntries){
    for(const a of aliases){
      let pos=t.indexOf(a);
      while(pos>=0){
        candidates.push({account,alias:a,start:pos,end:pos+a.length});
        pos=t.indexOf(a,pos+a.length);
      }
    }
  }

  // Priorizar el alias más específico para evitar que "galicia"
  // también matchee dentro de "tarjeta galicia".
  candidates.sort((a,b)=>(b.alias.length-a.alias.length)||(a.start-b.start));
  const selected=[];
  for(const c of candidates){
    const overlaps=selected.some(s=>c.start<s.end && c.end>s.start);
    if(!overlaps) selected.push(c);
  }
  selected.sort((a,b)=>a.start-b.start);

  // Una sola mención por cuenta canónica.
  const seen=new Set();
  return selected.filter(m=>{
    if(seen.has(m.account)) return false;
    seen.add(m.account);
    return true;
  });
}

function accountsFromText(){
  return accountMentionsFromText().map(m=>m.account);
}

function explicitTransferDirection(){
  const mentions=accountMentionsFromText();
  if(mentions.length<2) return null;

  const desde=t.indexOf(' desde ');
  if(desde>=0){
    const origin=mentions.find(m=>m.start>desde);
    if(!origin) return null;

    // "transferencia a Balanz desde Galicia"
    const before=mentions.filter(m=>m.end<=desde);
    if(before.length){
      const destination=before[before.length-1];
      return {origin:origin.account,destination:destination.account};
    }

    // "transferencia desde Galicia a Balanz" / "hacia Balanz"
    const after=mentions.filter(m=>m.start>origin.end);
    if(after.length){
      return {origin:origin.account,destination:after[0].account};
    }
  }

  // "transferencia de Galicia a Balanz"
  const de=t.indexOf(' de ');
  if(de>=0){
    const origin=mentions.find(m=>m.start>de);
    if(origin){
      const after=mentions.filter(m=>m.start>origin.end);
      if(after.length) return {origin:origin.account,destination:after[0].account};
    }
  }

  return null;
}

function externalAccountKey(row){
  const desc=String(row?.['Descripción original']||'');
  const cuit=(desc.match(/\b(\d{11})\b/)||[])[1]||'';
  const account=(desc.match(/\b(\d{18,22})\b/)||[])[1]||'';
  if(!account) return null;
  return `${row.Origen}|CTAEXT|${cuit||'SINCUIT'}|${account}`;
}

function complete(r,special){
  if(special==='AJUSTE_GASTO') return !!r['Categoría sugerida'] && (!!r['Cuenta origen'] || !!r['Cuenta destino']);
  const c=r['Clase sugerida'];
  if(!c || c==='Otro') return false;
  if(c==='Egreso') return !!r['Categoría sugerida'] && !!r['Cuenta origen'];
  if(c==='Ingreso') return !!r['Cuenta destino'];
  if(c==='Transferencia' || c==='Pago tarjeta') return !!r['Cuenta origen'] && !!r['Cuenta destino'];
  if(c==='Resultado financiero') return !!r['Cuenta origen'] || !!r['Cuenta destino'];
  return true;
}

if(ctx.type==='import_control_error'){
  if(/^(cancelar|cancelo|no|descartar|anular)$/i.test(text.trim()))
