  return [{json:{...x,route:'clarify',followup:`⚠️ ${why}\n\nNo se registrará nada mientras esté bloqueado. Podés responder "cancelar". Si el sistema reconoce una solución determinística, la próxima versión debe resolverla sin intervención externa.`}}];
}

if(ctx.type==='import_confirm'){
