  return [{json:{...x,route:'resolved',resolution:{discard:true,learnable:false,special:null}}}];
}

const r={...row};
let special=null;
let changed=false;
let learnable=false;
let applyGroup=/\b(todos|todas)\b/.test(t);
const forceVariable=/(preguntar siempre|preguntame siempre|pregúntame siempre|preguntá siempre|clasificacion variable|clasificación variable)/.test(t);
const noLearn=/(solo esta vez|sólo esta vez|no aprender|no aprendas|sin aprender|no guardar regla|no guardes regla)/.test(t);

// La cuenta agregadora Mercado Pago/Mercado Libre NO se considera billetera propia.
// Si el usuario explícitamente responde "transferencia a Mercado Pago Titular A/Titular B",
// lo resolverá la lógica genérica de cuentas de abajo. Nunca se aprende esa cuenta agregadora.

// Compra/venta de dólares del Galicia: es patrimonial, no gasto/ingreso.
// También resuelve filas que ya estaban en staging antes de instalar v40.
const rowNorm=norm(row['Descripción original']);

// Balanz en Galicia USD: resolver incluso si esta fila quedó staged antes de instalar v89.
const rowCuit=(String(row['CUIT contraparte']||'').replace(/\D/g,'') ||
  ((String(row['Descripción original']||'').match(/\b((?:20|23|24|27|30|33|34)\d{9})\b/)||[])[1]||''));
if(
  String(row['Cuenta/Tarjeta']||'')==='Galicia USD Titular A' &&
  (rowCuit==='00000000000' || rowNorm.includes('balanz capital valor'))
){
  const incoming=!!row['Cuenta destino'] || String(row['Clase sugerida']||'')==='Ingreso';
  return [{json:{...x,route:'resolved',resolution:{
    discard:false,
    clase:'Transferencia',
    subtipo:incoming?'Rescate inversión':'Aporte inversión',
    cuenta_origen:incoming?'Balanz':'Galicia USD Titular A',
    cuenta_destino:incoming?'Galicia USD Titular A':'Balanz',
    categoria:null,
    special:incoming?'RESCATE_BALANZ_USD':'APORTE_BALANZ_USD',
    learnable:false,
    account_mapping_key:null,
    learning_key:null,
    apply_group:false,
    force_variable:false,
    no_learn:true,
    contraparte_nombre:'Balanz Capital Valores',
    identidad_confirmada:true
  }}}];
}

// Si el lote ya estaba en revisión antes de instalar v88, resolver FCI PREMIUM
// de forma determinística al recibir el siguiente mensaje del usuario.
if(rowNorm.includes('suscripcion fci premium')){
  return [{json:{...x,route:'resolved',resolution:{
    discard:false,
    clase:'Transferencia',
    subtipo:'Aporte inversión',
    cuenta_origen:'Nación',
    cuenta_destino:'Pellegrini +',
    categoria:null,
    special:'APORTE_PELLEGRINI',
    learnable:false,
    account_mapping_key:null,
    learning_key:null,
    apply_group:false,
    force_variable:false,
    no_learn:true,
    contraparte_nombre:null,
    identidad_confirmada:false
  }}}];
}
if(rowNorm.includes('rescate fci premium')){
  return [{json:{...x,route:'resolved',resolution:{
    discard:false,
    clase:'Transferencia',
    subtipo:'Rescate inversión',
    cuenta_origen:'Pellegrini +',
    cuenta_destino:'Nación',
    categoria:null,
    special:'RESCATE_PELLEGRINI',
    learnable:false,
    account_mapping_key:null,
    learning_key:null,
    apply_group:false,
    force_variable:false,
    no_learn:true,
    contraparte_nombre:null,
    identidad_confirmada:false
  }}}];
}

const isFxPurchase=(rowNorm.includes('compra venta de dolares') || rowNorm.includes('compra moneda extran')) &&
                   !rowNorm.includes('venta moneda extran');
const isFxSale=rowNorm.includes('venta moneda extran') && !rowNorm.includes('compra moneda extran');

if((isFxPurchase || isFxSale) &&
   /(dolar|dólar|usd|moneda extranjera|compra|venta|galicia)/.test(t)){
  return [{json:{...x,route:'resolved',resolution:{
    discard:false,
    clase:'Transferencia',
    subtipo:isFxSale?'Venta de moneda extranjera':'Compra de moneda extranjera',
    cuenta_origen:isFxSale?'Galicia USD Titular A':'Galicia Titular A',
    cuenta_destino:isFxSale?'Galicia Titular A':'Galicia USD Titular A',
    categoria:null,
    special:isFxSale?'FX_VENTA_USD':'FX_COMPRA_USD',
    learnable:false,
    account_mapping_key:null,
    apply_group:false,
    force_variable:false,
    contraparte_nombre:null,
    identidad_confirmada:false
  }}}];
}

const cat=catFromText();
const accs=accountsFromText();
const explicitDirection=explicitTransferDirection();
const counterpartName=counterpartyFromText();

// Aceptar una sugerencia aprendida
if(/^(si|sí|correcto|dale|ok|esa|ese)$/i.test(text.trim()) && r['Categoría sugerida']){
  changed=true; learnable=true;
}

if(counterpartName){
  r['Contraparte sugerida']=counterpartName;
  changed=true;
}

// Crédito que el usuario confirma como devolución/reintegro de un gasto.
// Puede venir con una descripción bancaria genérica (ej. "CRÉDITO TRANSFERENCIA").
// Solo se usa si el usuario explícitamente pide reducir/contrarrestar una categoría.
const descNorm=norm(r['Descripción original']);
const rowLooksCredit=
  !!r['Cuenta destino'] ||
  ['Ingreso','Resultado financiero'].includes(String(r['Clase sugerida']||'')) ||
  descNorm.includes('credito transferencia') ||
  descNorm.includes('reintegro') ||
  descNorm.includes('benef ');

const explicitExpenseReduction=
  (!!cat && (
    String(row['Subtipo']||'').toLowerCase().includes('reintegro') ||
    descNorm.includes('benef pei-cuenta dni') ||
    descNorm.includes('reintegro')
  )) ||
  (/(rest|reduc|descont|contra el gasto|contra gasto|devolucion(?: de gasto)?|devolución(?: de gasto)?|reintegro)/.test(t) && !!cat) ||
  // Crédito + respuesta explícita "gasto <categoría>" = devolución/reintegro que reduce ese gasto.
  (rowLooksCredit && /\bgasto\b/.test(t) && !!cat);

// Regla familiar: si es un CRÉDITO y el usuario responde "Cositas de Casa",
// interpretarlo como ingreso del emprendimiento. No aprender nunca por contraparte/CUIT.
const cositasIncome=
  rowLooksCredit &&
  cat==='Cositas de Casa' &&
  !explicitExpenseReduction &&
  !/\bgasto\b/.test(t);

const incomeCategorySelected=
  rowLooksCredit &&
  !!cat &&
  incomeCategories.includes(cat) &&
  !explicitExpenseReduction &&
  !/\bgasto\b/.test(t);

if(cositasIncome){
  r['Clase sugerida']='Ingreso';
  r.Subtipo='Ingreso Cositas de Casa';
  r['Categoría sugerida']='Cositas de Casa';
  r['Cuenta destino']=r['Cuenta destino']||r['Cuenta/Tarjeta']||null;
  changed=true;
  learnable=false;
} else if(incomeCategorySelected){
  r['Clase sugerida']='Ingreso';
  r.Subtipo=cat==='Otros ingresos'?'Otro':cat;
  r['Categoría sugerida']=cat;
  r['Cuenta destino']=r['Cuenta destino']||r['Cuenta/Tarjeta']||null;
  changed=true;
  learnable=false;
} else if(rowLooksCredit && explicitExpenseReduction){
  special='AJUSTE_GASTO';
  r['Clase sugerida']='Egreso';
  r['Subtipo']='Ajuste / reintegro de gasto';
  r['Categoría sugerida']=cat;
  changed=true;
  const merchantKey=merchantLearningKey(row);
  learnable=!!merchantKey;
  applyGroup=!!merchantKey;
} else {
  if(cat){
    r['Categoría sugerida']=cat;
    changed=true;
    if(r['Aprendible']==='Sí') learnable=true;

    // Si el extracto ya demuestra que fue un débito desde una cuenta nuestra
    // y el usuario responde una categoría de gasto, esa respuesta define que
    // NO era una transferencia interna: es un Egreso desde la cuenta origen.
    if(
      r['Cuenta origen'] &&
      !r['Cuenta destino'] &&
      ['Otro','Transferencia'].includes(String(r['Clase sugerida']||''))
    ){
      r['Clase sugerida']='Egreso';
      r.Subtipo=String(r.Subtipo||'').toLowerCase().includes('transfer')
        ?'Gasto / transferencia a tercero'
        :(r.Subtipo||'Otro');
    } else if(r['Clase sugerida']==='Otro' && r['Cuenta origen']){
      r['Clase sugerida']='Egreso';
    }
  }

  if(/\bgasto\b/.test(t)){r['Clase sugerida']='Egreso';changed=true;}
  if(/\bingreso\b/.test(t)){r['Clase sugerida']='Ingreso';changed=true;}
  if(/\btransferencia\b/.test(t)){r['Clase sugerida']='Transferencia';changed=true;}
  if(/resultado financiero|rendimiento|interes|interés/.test(t)){r['Clase sugerida']='Resultado financiero';changed=true;}
  if(/pago (de )?tarjeta/.test(t)){r['Clase sugerida']='Pago tarjeta';changed=true;}

  if(accs.length){
    if(r['Clase sugerida']==='Transferencia' || r['Clase sugerida']==='Pago tarjeta'){
      // Si el usuario escribió dirección explícita, manda esa dirección.
      if(explicitDirection){
        r['Cuenta origen']=explicitDirection.origin;
        r['Cuenta destino']=explicitDirection.destination;
        changed=true;
      } else if(!r['Cuenta origen'] && r['Cuenta destino']){
        // El PDF ya indicó que el dinero ENTRÓ en la cuenta del resumen:
        // la cuenta mencionada por el usuario completa el origen.
        const candidate=accs.find(a=>a!==r['Cuenta destino']);
        if(candidate){r['Cuenta origen']=candidate;changed=true;}
      } else if(r['Cuenta origen'] && !r['Cuenta destino']){
        // El PDF ya indicó que el dinero SALIÓ de la cuenta del resumen:
        // la cuenta mencionada por el usuario completa el destino.
        const candidate=accs.find(a=>a!==r['Cuenta origen']);
        if(candidate){r['Cuenta destino']=candidate;changed=true;}
      } else if(!r['Cuenta origen'] && !r['Cuenta destino'] && accs.length===1){
        // Con una sola cuenta nombrada y sin dirección documental,
        // no adivinar origen/destino.
      } else if(!r['Cuenta origen'] && !r['Cuenta destino'] && accs.length>=2){
        // Dos cuentas sin "desde/de ... a/hacia ...": tampoco adivinar.
      }
    } else if(r['Clase sugerida']==='Egreso'){
      r['Cuenta origen']=accs[0];changed=true;
    } else if(r['Clase sugerida']==='Ingreso' || r['Clase sugerida']==='Resultado financiero'){
      r['Cuenta destino']=accs[0];changed=true;
    } else if(!r['Cuenta origen'] && !r['Cuenta destino'] && accs.length===1){
      // No decidir dirección si todavía no sabemos qué tipo de movimiento es.
    }
  }
}

if(changed && complete(r,special)){
  const accountKey=(r['Clase sugerida']==='Transferencia')?externalAccountKey(r):null;
  const merchantKey=merchantLearningKey(row);
  const recipientKey=mpRecipientLearningKey(row);
  const recipientLearnable=!!recipientKey && r['Clase sugerida']==='Egreso' && !!r['Categoría sugerida'];
  const accountLearnable=!!accountKey && !!r['Cuenta origen'] && !!r['Cuenta destino'];
  if(recipientLearnable) learnable=true;

  const currentDescUpper=String(row['Descripción original']||'').toUpperCase();
  const protectedCounterparty=
    currentDescUpper.includes('DI BENEDETTO') ||
    currentDescUpper.includes('00000000000');
  const protectedCositasIncome=
    r['Clase sugerida']==='Ingreso' &&
    r['Categoría sugerida']==='Cositas de Casa';
  const effectiveNoLearn=noLearn || protectedCounterparty || protectedCositasIncome;

  return [{json:{...x,route:'resolved',resolution:{
    discard:false,
    clase:r['Clase sugerida']||null,
    subtipo:r.Subtipo||null,
    cuenta_origen:r['Cuenta origen']||null,
    cuenta_destino:r['Cuenta destino']||null,
    categoria:r['Categoría sugerida']||null,
    special,
    learnable:effectiveNoLearn?false:(accountLearnable?true:learnable),
    account_mapping_key:effectiveNoLearn?null:accountKey,
    learning_key:effectiveNoLearn?null:(recipientKey||merchantKey||row['Clave aprendizaje']||null),
    apply_group:effectiveNoLearn?false:(accountLearnable?true:applyGroup),
    force_variable:protectedCounterparty?true:(effectiveNoLearn?false:forceVariable),
    no_learn:effectiveNoLearn,
    contraparte_nombre:counterpartName||null,
    identidad_confirmada:!!counterpartName
  }}}];
}

// Antes de gastar IA, repreguntar datos materiales simples.
if(r['Clase sugerida']==='Transferencia' && (!r['Cuenta origen'] || !r['Cuenta destino'])){
  return [{json:{...x,route:'clarify',followup:'Entendido. Decime origen y destino, por ejemplo: "de Mercado Pago Titular B a Provincia Titular B".'}}];
}
if(r['Clase sugerida']==='Egreso' && !r['Categoría sugerida']){
  return [{json:{...x,route:'clarify',followup:'Entendido. ¿A qué categoría corresponde el gasto?'}}];
}
if((!r['Clase sugerida'] || r['Clase sugerida']==='Otro') && row['CUIT contraparte']){
  return [{json:{...x,route:'clarify',followup:'¿Fue un gasto, una transferencia, un ingreso u otro tipo de movimiento?'}}];
}

return [{json:{...x,route:'ai'}}];

const d=$('Detectar pendiente importación').first().json;
const ctx=d.context, m=ctx.meta||{}, lot=ctx.lotId, c=m.cardSummary||{};
const rows=$('Leer revisión para confirmar').all().map(i=>i.json).filter(r=>String(r['Lote ID'])===String(lot));
function interp(r){try{return JSON.parse(r['Respuesta interpretada']||'{}');}catch(e){return {};}}
let ingresos=0,egresos=0,transf=0;
for(const r of rows){
  if(!['LISTO','RESPONDIDO'].includes(String(r.Estado))) continue;
  let a=r['Monto ARS']; a=(a===null||a===undefined||a==='')?0:Number(a);
  if(interp(r).special==='AJUSTE_GASTO') a=-Math.abs(a);
  if(r['Clase sugerida']==='Ingreso') ingresos+=a;
  if(r['Clase sugerida']==='Egreso') egresos+=a;
  if(['Transferencia','Pago tarjeta'].includes(r['Clase sugerida'])) transf+=Math.abs(a);
}
const discardedRows=rows.filter(r=>String(r.Estado)==='DESCARTADO');
const mirrorRows=discardedRows.filter(r=>
  String(r.Observaciones||'').startsWith('ESPEJO CONCILIADO') ||
  (()=>{try{return !!JSON.parse(r['Respuesta interpretada']||'{}').mirror;}catch(e){return false;}})()
);
const mirrors=mirrorRows.length;
const discarded=discardedRows.length;
const discardedReal=Math.max(0,discarded-mirrors);
const internalNew=rows.filter(r=>
  ['LISTO','RESPONDIDO'].includes(String(r.Estado)) &&
  String(r['Clase sugerida']||'')==='Transferencia' &&
  ['Transferencia propia','Aporte inversión','Rescate inversión','Extracción efectivo','Depósito efectivo']
    .includes(String(r.Subtipo||''))
).length;
const now=new Date().toISOString();
return [{json:{
  importRow:{
    "Lote ID":lot,"Fecha carga":m.created_at||now,"Tipo documento":m.docType,
    "Institución":m.origin,"Cuenta / tarjeta":m.account,
