let conflicts=Number(old.Conflictos||0);

let state,confidence,outValue,note;

if(wasVariable){
  // VARIABLE ya no es irreversible. Guardamos la racha en Nota sin cambiar el esquema de la hoja.
  const oldNote=String(old.Nota||'');
  const lastMatch=oldNote.match(/(?:última respuesta|última clasificación)\s*:\s*([^.]+)(?:\.|$)/i);
  const lastValue=lastMatch ? String(lastMatch[1]||'').trim() : '';
  const streakMatch=oldNote.match(/racha\s*:\s*(\d+)/i);
  const priorStreak=streakMatch ? Number(streakMatch[1]||0) : (lastValue ? 1 : 0);
  const sameAsLast=lastValue && String(lastValue).toLowerCase()===String(value).trim().toLowerCase();
  const streak=sameAsLast ? priorStreak+1 : 1;

  if(lastValue && !sameAsLast) conflicts+=1;

  if(streak>=2){
    state='AUTO';
    confidence=(isAccount||isMerchant||key.includes('|CUIT|'))?1:0.97;
    outValue=value;
    note=`Regla recuperada después de ${streak} confirmaciones consecutivas: ${value}.`;
  } else {
    state='VARIABLE';
    confidence=0.70;
    outValue='VARIABLE';
    note=`Asignación variable detectada. Racha: ${streak}; última respuesta: ${value}. Reconfirmar una vez más para recuperar AUTO.`;
  }
} else {
  const same=previousValue===String(value).trim();
  if(same){
    if(isAccount){
      state='AUTO'; confidence=1; outValue=value;
      note=`Cuenta externa reconfirmada: ${value}.`;
    } else if(isMerchant){
      state='AUTO'; confidence=1; outValue=value;
      note=`Comercio reconfirmado: ${value}.`;
    } else {
      state=confirmations>=2?'AUTO':'SUGERIR';
      confidence=confirmations>=2?0.97:0.90;
      outValue=value;
      note=confirmations>=2?`Clasificación repetida: ${value}.`:`Sugerencia: ${value}.`;
    }
  } else {
    conflicts+=1;
    state='VARIABLE'; confidence=0.60; outValue='VARIABLE';
    note=`Asignación variable detectada. Racha: 1; última respuesta: ${value}. Reconfirmar una vez más para recuperar AUTO.`;
  }
}

