const p=$json;
const rows=Array.isArray(p.rows)?p.rows:[];
function up(s){return String(s??'').toUpperCase();}
const has=rows.some(r=>{
  if(String(r.Estado||'')==='DESCARTADO') return false;
  const clase=String(r['Clase sugerida']||'');
  const sub=up(r.Subtipo);
  const desc=up(r['Descripción original']);
  const transferish=
    clase==='Transferencia' ||
    sub.includes('TRANSFER') ||
    desc.includes('TRANSFER') ||
    desc.includes('TRANSF.') ||
    desc.includes('TRANSF ') ||
    desc.includes('DEBIN');
  const oneSide=
    !!String(r['Cuenta origen']||'').trim() ||
    !!String(r['Cuenta destino']||'').trim() ||
    !!String(r['Cuenta/Tarjeta']||'').trim();
  return transferish && oneSide;
});
return [{json:{...p,_has_internal_transfers:has}}];

const parsed=$('Detectar transferencias internas').first().json;
const existing=$('Leer movimientos para espejos').all().map(i=>i.json).filter(r=>Object.keys(r||{}).length>0);
const accountRows=$('Leer cuentas propias para espejos').all().map(i=>i.json).filter(r=>Object.keys(r||{}).length>0);
const mapRows=$('Leer mapeo propio para espejos').all().map(i=>i.json).filter(r=>Object.keys(r||{}).length>0);
const rows=(parsed.rows||[]).map(r=>({...r}));
const lot=String(parsed.meta?.lotId||'');

function norm(s){
  return String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toUpperCase().replace(/\s+/g,' ').trim();
}
function digits(s){return String(s??'').replace(/\D/g,'');}
function yes(v){return ['SI','SÍ','TRUE','1'].includes(norm(v));}
function dateObj(v){
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number'){
    return new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000);
  }
  const s=String(v).trim();
  let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if(m) return new Date(Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3])));
  m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if(m) return new Date(Date.UTC(Number(m[3]),Number(m[2])-1,Number(m[1])));
  return null;
}
function dayDiff(a,b){
  const da=dateObj(a), db=dateObj(b);
  if(!da||!db) return 999;
  return Math.abs((da-db)/86400000);
}
function currency(r){
  const c=norm(r['Moneda original']||'ARS');
  return c||'ARS';
}
function amount(r){
  const c=currency(r);
  if(c!=='ARS'){
    const n=Number(r['Monto original']);
    return Number.isFinite(n)?Math.abs(n):null;
  }
  const n=Number(r['Monto ARS']);
  return Number.isFinite(n)?Math.abs(n):null;
}
function transferish(r){
  const cl=String(r['Clase sugerida']||'');
  const su=norm(r.Subtipo);
  const de=norm(r['Descripción original']);
  return cl==='Transferencia' || su.includes('TRANSFER') || de.includes('TRANSFER') || de.includes('TRANSF') || de.includes('DEBIN');
}

const accountType=new Map();
const ownAccounts=new Set();
for(const r of accountRows){
  const name=String(r.Cuenta||'').trim();
  if(!name) continue;
  if(r.Activa!==undefined && String(r.Activa).trim()!=='' && !yes(r.Activa)) continue;
  ownAccounts.add(name);
  accountType.set(name,norm(r.Tipo));
}

const mappings=[];
for(const r of mapRows){
  if(norm(r.Estado)!=='CONFIRMADO') continue;
  const acc=String(r['Cuenta sistema']||'').trim();
  const id=String(r.Identificador||'').trim();
  if(!acc || !id || !ownAccounts.has(acc)) continue;
  mappings.push({
    account:acc,
    id,
    idDigits:digits(id),
    idNorm:norm(id)
  });
}

function inferMappedCounterparty(r){
  const desc=String(r['Descripción original']||'');
  const dNorm=norm(desc);
  const dDigits=digits(desc);
  const statement=String(r['Cuenta/Tarjeta']||'').trim();

  const found=new Set();

  for(const m of mappings){
    if(m.account===statement) continue;
    let hit=false;
    if(m.idDigits.length>=6 && dDigits.includes(m.idDigits)) hit=true;
    if(!hit && m.idNorm.length>=5 && dNorm.includes(m.idNorm)) hit=true;
    if(hit) found.add(m.account);
  }

  // También usar nombres de cuentas de inversión/sistema cuando aparecen textualmente.
  for(const a of ownAccounts){
    if(a===statement) continue;
    const an=norm(a);
    if(an.length>=4 && dNorm.includes(an)) found.add(a);
  }

  if(found.size===1) return [...found][0];
  return null;
}

function directionFromRow(r){
  const statement=String(r['Cuenta/Tarjeta']||'').trim();
  const from=String(r['Cuenta origen']||'').trim();
  const to=String(r['Cuenta destino']||'').trim();
  const d=norm(r['Descripción original']);

  if(from && ownAccounts.has(from)) return 'OUT';
  if(to && ownAccounts.has(to)) return 'IN';

  if(statement && ownAccounts.has(statement)){
    if(
      d.includes('RECIBIDA') || d.includes('DE TERCEROS') || d.includes('CREDITO') ||
      d.includes('CR.TRANSF') || d.includes('CR. TRANSF') || d.startsWith('DEBIN ')
    ) return 'IN';
    if(
      d.includes('ENVIADA') || d.includes('A TERCEROS') || d.includes('DEBITO') ||
      d.includes('DB.TRANSF') || d.includes('DEB. TRANSF') || d.includes('PAGO CON TRANSFERENCIA')
    ) return 'OUT';
  }
  return null;
}

function subtypeFor(from,to,canonicalSub=null){
  if(canonicalSub) return canonicalSub;
  const tf=accountType.get(from)||'';
  const tt=accountType.get(to)||'';
  if(tt.includes('INVERSION') || tt.includes('INVERSIÓN')) return 'Aporte inversión';
  if(tf.includes('INVERSION') || tf.includes('INVERSIÓN')) return 'Rescate inversión';
  if(to==='Efectivo' || to==='Efectivo USD') return 'Extracción efectivo';
  if(from==='Efectivo' || from==='Efectivo USD') return 'Depósito efectivo';
  return 'Transferencia propia';
}

// Precompletar punta faltante por identificadores/nombres propios confirmados.
let inferredByMap=0;
for(const r of rows){
  if(String(r.Estado||'')==='DESCARTADO' || !transferish(r)) continue;

  const statement=String(r['Cuenta/Tarjeta']||'').trim();
  if(!statement || !ownAccounts.has(statement)) continue;

  const dir=directionFromRow(r);
  const mapped=inferMappedCounterparty(r);
  if(!mapped || mapped===statement) continue;

  if(dir==='OUT' && !String(r['Cuenta destino']||'').trim()){
    r['Cuenta origen']=String(r['Cuenta origen']||statement);
    r['Cuenta destino']=mapped;
    r['Clase sugerida']='Transferencia';
    r.Subtipo=subtypeFor(r['Cuenta origen'],r['Cuenta destino']);
    r['Categoría sugerida']=null;
    r.Confianza=1;
    r.Estado='LISTO';
    r['Motivo revisión']='Contraparte propia inferida desde Mapeo_Cuentas';
    r.Pregunta=null;
    r['Clave aprendizaje']=null;
    r.Aprendible='No';
    inferredByMap++;
  }else if(dir==='IN' && !String(r['Cuenta origen']||'').trim()){
    r['Cuenta origen']=mapped;
    r['Cuenta destino']=String(r['Cuenta destino']||statement);
    r['Clase sugerida']='Transferencia';
    r.Subtipo=subtypeFor(r['Cuenta origen'],r['Cuenta destino']);
    r['Categoría sugerida']=null;
    r.Confianza=1;
    r.Estado='LISTO';
    r['Motivo revisión']='Contraparte propia inferida desde Mapeo_Cuentas';
    r.Pregunta=null;
    r['Clave aprendizaje']=null;
    r.Aprendible='No';
    inferredByMap++;
  }
}

// Movimientos canónicos internos existentes.
const movements=existing.filter(m=>
  String(m.Clase||'')==='Transferencia' &&
  String(m['Lote importación']||'')!==lot &&
  !!String(m.ID||'').trim() &&
  ownAccounts.has(String(m['Cuenta origen']||'')) &&
  ownAccounts.has(String(m['Cuenta destino']||''))
);

const candidates=rows
  .map((r,idx)=>({r,idx}))
  .filter(x=>{
    if(String(x.r.Estado||'')==='DESCARTADO' || !transferish(x.r)) return false;
    const statement=String(x.r['Cuenta/Tarjeta']||'').trim();
    const from=String(x.r['Cuenta origen']||'').trim();
    const to=String(x.r['Cuenta destino']||'').trim();
    return ownAccounts.has(statement) || ownAccounts.has(from) || ownAccounts.has(to);
  });

const used=new Set();
const matched=new Map();

function compatible(x,m,maxDays){
  if(used.has(String(m.ID))) return false;

  const a=amount(x.r), ma=amount(m);
  if(a===null||ma===null||Math.abs(a-ma)>0.005) return false;
  if(currency(x.r)!==currency(m)) return false;
  if(dayDiff(m.Fecha,x.r.Fecha)>maxDays) return false;

  const rf=String(x.r['Cuenta origen']||'').trim();
  const rt=String(x.r['Cuenta destino']||'').trim();
  const st=String(x.r['Cuenta/Tarjeta']||'').trim();
  const dir=directionFromRow(x.r);

  if(rf && ownAccounts.has(rf) && String(m['Cuenta origen']||'')!==rf) return false;
  if(rt && ownAccounts.has(rt) && String(m['Cuenta destino']||'')!==rt) return false;

  if(!rf && !rt && st && ownAccounts.has(st)){
    if(dir==='OUT' && String(m['Cuenta origen']||'')!==st) return false;
    if(dir==='IN' && String(m['Cuenta destino']||'')!==st) return false;
  }else{
    if(!rf && dir==='OUT' && st && String(m['Cuenta origen']||'')!==st) return false;
    if(!rt && dir==='IN' && st && String(m['Cuenta destino']||'')!==st) return false;
  }

  return true;
}

function listFor(x,maxDays){
  const list=movements.filter(m=>compatible(x,m,maxDays))
    .sort((a,b)=>dayDiff(a.Fecha,x.r.Fecha)-dayDiff(b.Fecha,x.r.Fecha));

  if(list.length<=1) return list;

  // Si hay varias opciones, solo es seguro si todas representan la misma pareja
  // origen/destino. En ese caso una asignación 1 a 1 arbitraria es equivalente.
  const pairs=new Set(list.map(m=>`${m['Cuenta origen']}|${m['Cuenta destino']}`));
  if(pairs.size===1) return list;

  // Si el mejor tiene fecha estrictamente más cercana que el segundo, es inequívoco.
  const d0=dayDiff(list[0].Fecha,x.r.Fecha);
  const d1=dayDiff(list[1].Fecha,x.r.Fecha);
  return d0<d1 ? [list[0]] : [];
}

// Exactos primero.
for(const x of candidates){
  const m=listFor(x,0)[0];
  if(m){
    matched.set(x.idx,m);
    used.add(String(m.ID));
  }
}

// Después hasta 3 días, siempre por menor diferencia.
let remaining=candidates.filter(x=>!matched.has(x.idx));
while(remaining.length){
  let best=null;
  for(const x of remaining){
    const m=listFor(x,3)[0];
    if(!m) continue;
    const delta=dayDiff(m.Fecha,x.r.Fecha);
    if(!best || delta<best.delta){
      best={x,m,delta};
    }
  }
  if(!best) break;
  matched.set(best.x.idx,best.m);
  used.add(String(best.m.ID));
  remaining=remaining.filter(x=>x.idx!==best.x.idx);
}

let mirrorCount=0;
for(const [idx,m] of matched.entries()){
  const r=rows[idx];
  const delta=dayDiff(m.Fecha,r.Fecha);

  // Completar ambas puntas desde el movimiento canónico.
  r['Cuenta origen']=m['Cuenta origen'];
  r['Cuenta destino']=m['Cuenta destino'];
  r['Clase sugerida']='Transferencia';
  r.Subtipo=subtypeFor(r['Cuenta origen'],r['Cuenta destino'],m.Subtipo||null);
  r['Categoría sugerida']=null;

  r.Estado='DESCARTADO';
  r['ID movimiento final']=m.ID;
  r.Confianza=1;
  r['Motivo revisión']='Espejo conciliado con transferencia canónica ya registrada';
  r.Pregunta=null;
  r.Observaciones=`ESPEJO CONCILIADO con ${m.ID} (${m['Origen dato']||'Movimientos'}); diferencia de fecha ${delta} día(s).`;
  r['Respuesta interpretada']=JSON.stringify({
    mirror:true,
    canonical_id:m.ID,
    canonical_reference:m.Referencia||null,
    date_delta_days:delta,
    from:r['Cuenta origen'],
    to:r['Cuenta destino'],
    currency:currency(r)
  });
  r['Fecha resolución']=new Date().toISOString();
  r['Clave aprendizaje']=null;
  r.Aprendible='No';
  mirrorCount++;
}

// Transferencias nuevas con dos cuentas propias: quedan listas como canónicas,
// aun cuando la contraparte todavía no haya sido cargada desde el otro resumen.
let newInternal=0;
for(const r of rows){
  if(String(r.Estado||'')==='DESCARTADO' || !transferish(r)) continue;
  const from=String(r['Cuenta origen']||'').trim();
  const to=String(r['Cuenta destino']||'').trim();
  if(ownAccounts.has(from) && ownAccounts.has(to)){
    r['Clase sugerida']='Transferencia';
    r.Subtipo=subtypeFor(from,to,r.Subtipo||null);
    r['Categoría sugerida']=null;
    r.Confianza=Math.max(Number(r.Confianza||0),1);
    r.Estado='LISTO';
    r['Motivo revisión']='Transferencia entre cuentas propias; queda canónica hasta encontrar espejo';
    r.Pregunta=null;
    r['Clave aprendizaje']=null;
    r.Aprendible='No';
    newInternal++;
  }
}

const meta={...(parsed.meta||{})};
meta.ready=rows.filter(r=>String(r.Estado)==='LISTO').length;
meta.review=rows.filter(r=>String(r.Estado)==='REVISAR').length;
meta.discarded=rows.filter(r=>String(r.Estado)==='DESCARTADO').length;
meta.mirrors=(Number(meta.mirrors)||0)+mirrorCount;
meta.internal_new=(Number(meta.internal_new)||0)+newInternal;
meta.internal_inferred_by_map=(Number(meta.internal_inferred_by_map)||0)+inferredByMap;
meta.totalRows=rows.length;

return [{json:{
  ...parsed,
  rows,
  meta,
  _mirror_matches:mirrorCount,
  _internal_new:newInternal,
  _internal_inferred_by_map:inferredByMap
}}];

const src=$('Parsear PDF real').first().json;
const out=JSON.parse(JSON.stringify(src));
const m=out.meta||{};
const rows=Array.isArray(out.rows)?out.rows:[];
const dc=m.documentControl||{};
const cards=$('Leer tarjetas control previo').all().map(i=>i.json).filter(Boolean);
const sessions=$('Leer cierre activo control previo').all().map(i=>i.json).filter(Boolean);
function dateKey(v){
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number'){const d=new Date(Date.UTC(1899,11,30)+Number(v)*86400000);return d.toISOString().slice(0,10);}
  const s=String(v);let z=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(z)return `${z[1]}-${z[2]}-${z[3]}`;
  z=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);if(z){let y=+z[3];if(y<100)y+=2000;return `${y}-${String(+z[2]).padStart(2,'0')}-${String(+z[1]).padStart(2,'0')}`;}return null;
}
function n(v){const x=Number(v);return Number.isFinite(x)?x:0;}
const close=dateKey(m.cardSummary?.close||m.periodTo);
const active=sessions
  .filter(r=>r.Periodo && !['CERRADO','CANCELADO','CANCELADO_USUARIO'].includes(String(r.Estado||'').toUpperCase()))
  .sort((a,b)=>String(b['Última actualización']||b.Inicio||'').localeCompare(String(a['Última actualización']||a.Inicio||'')))[0]||null;

// Si hay un cierre mensual activo y la tarjeta pertenece a otro mes, NO bloquear un
// documento válido. Se importa en su mes real y 06 decidirá si recalcula un mes cerrado.
// Lo importante es que nunca satisfaga por error el checklist del mes activo.
if(active && /^tarjeta_/.test(String(m.docType||'')) && close){
  const docMonth=close.slice(0,7), activeMonth=String(active.Periodo||'').slice(0,7);
  if(activeMonth && docMonth!==activeMonth){
    m.diagnostic={
      type:docMonth<activeMonth?'HISTORICO_TARDIO':'OTRO_MES',
      documentMonth:docMonth,activeMonth,
      message:`El resumen corresponde a ${docMonth}; se importará allí y no contará como documento de ${activeMonth}.`
    };
  }
}

// Si el resumen anterior de la misma tarjeta está efectivamente PAGADO, no arrastrar nuevamente
// saldo anterior residual/percepciones ya canceladas al control del resumen nuevo.
if(close && ['tarjeta_galicia','tarjeta_provincia'].includes(String(m.docType||''))){
  const prev=cards.filter(r=>String(r.Tarjeta||'')===String(m.account||'') && dateKey(r.Cierre||r.Periodo) && dateKey(r.Cierre||r.Periodo)<close)
    .sort((a,b)=>String(dateKey(b.Cierre||b.Periodo)).localeCompare(String(dateKey(a.Cierre||a.Periodo))))[0]||null;
  const paid=prev && (String(prev.Estado||'').toUpperCase()==='PAGADA' || (Math.abs(n(prev['Saldo pendiente ARS']))<0.01 && Math.abs(n(prev['Saldo pendiente USD']))<0.01));
  if(paid){
    const calcArs=rows.reduce((a,r)=>a+(r['Monto ARS']===null||r['Monto ARS']===undefined||r['Monto ARS']===''?0:n(r['Monto ARS'])),0);
    const calcUsd=rows.reduce((a,r)=>a+(String(r['Moneda original']||'').toUpperCase()==='USD'?n(r['Monto original']):0),0);
    const declArs=m.cardSummary?.totalArs;
    const declUsd=m.cardSummary?.totalUsd??0;
    if(declArs!==null&&declArs!==undefined){
      const da=calcArs-n(declArs), du=calcUsd-n(declUsd);
      if(Math.abs(da)<=0.02 && Math.abs(du)<=0.02){
        m.documentControl={...dc,level:'FUERTE',status:'OK',block:false,
          declaredTotalArs:n(declArs),calcTotalArs:calcArs,diffTotalArs:da,
          declaredTotalUsd:n(declUsd),calcTotalUsd:calcUsd,diffTotalUsd:du,
          message:'Control OK: el resumen anterior ya estaba pagado; no se vuelve a arrastrar su saldo residual. Los cargos del período coinciden con el total actual.'};
      }
    }
  }
}
return [{json:out}];

const hasCardPayment = $('Preparar movimientos confirmados').all()
  .some(i => String(i.json?.Clase || '') === 'Pago tarjeta');
return [{json:{has_card_payment:hasCardPayment}}];
